window.interviewData = window.interviewData || {};

// ─────────────────────────────────────────────────────────────────────────────
// AWS ▶ LB Basics
// ─────────────────────────────────────────────────────────────────────────────
window.interviewData["AWS ▶ LB Basics"] = {
  "Basic": [
    { q: "What is a Load Balancer and why do we need one?", a: "<strong>Detailed Solution:</strong> A Load Balancer distributes incoming application traffic across multiple backend targets (EC2 instances, containers, IPs, Lambda functions).<br><ul><li><strong>Why:</strong> No single server can serve unlimited concurrent users reliably. Without a load balancer, one instance handles everything — creating a single point of failure and a performance bottleneck.</li><li><strong>Benefits:</strong> Fault tolerance (if one instance crashes, traffic routes to healthy ones), scalability (add/remove servers seamlessly), and even distribution (prevents one server from being overwhelmed while others are idle).</li></ul>" },
    { q: "What are the different types of Load Balancers in AWS?", a: "<strong>Detailed Solution:</strong> AWS offers four types under Elastic Load Balancing (ELB).<br><ul><li><strong>ALB (Application Load Balancer):</strong> Layer 7 (HTTP/HTTPS). Best for web apps, microservices, host/path-based routing.</li><li><strong>NLB (Network Load Balancer):</strong> Layer 4 (TCP/UDP). Ultra-low latency, millions of requests/sec, static IPs.</li><li><strong>GWLB (Gateway Load Balancer):</strong> Layer 3. Routes traffic through third-party virtual appliances (firewalls, IDS/IPS).</li><li><strong>CLB (Classic Load Balancer):</strong> Legacy. Supports both Layer 4 and 7. AWS recommends migrating to ALB/NLB.</li></ul>" },
    { q: "What is a Target Group in AWS Load Balancing?", a: "<strong>Detailed Solution:</strong> A Target Group is a logical grouping of resources that a Load Balancer routes traffic to.<br><ul><li><strong>Members:</strong> Can contain EC2 instances, ECS containers, IP addresses, or Lambda functions.</li><li><strong>Health Checks:</strong> Each target group has its own health check configuration (path, port, thresholds). The LB only sends traffic to healthy targets.</li><li><strong>Usage:</strong> ALB listener rules route traffic to specific target groups based on host or path conditions.</li></ul>" },
    { q: "What is a Listener in a Load Balancer?", a: "<strong>Detailed Solution:</strong> A Listener is a process that checks for incoming connection requests using the protocol and port you configure.<br><ul><li><strong>Example:</strong> An ALB may have two listeners: one on port 80 (HTTP) and one on port 443 (HTTPS).</li><li><strong>Rules:</strong> Each listener has a default rule directing traffic to a default target group. You can add additional rules to route based on conditions.</li></ul>" },
    { q: "What is the difference between Layer 4 and Layer 7 load balancing?", a: "<strong>Detailed Solution:</strong> The OSI model layer determines how the LB inspects and routes traffic.<br><ul><li><strong>Layer 4 (Transport — NLB):</strong> Routes based solely on TCP/UDP source IP, destination IP, and port. It is extremely fast since it doesn't inspect packet contents.</li><li><strong>Layer 7 (Application — ALB):</strong> Fully inspects the HTTP request — URL path, headers, cookies, hostnames. Enables intelligent routing decisions (e.g., send <code>/api/*</code> to a backend service and <code>/static/*</code> to an S3 bucket).</li></ul>" },
    { q: "What is a Health Check in the context of a Load Balancer?", a: "<strong>Detailed Solution:</strong> Health checks are periodic probes sent by the LB to each target to determine if it can handle traffic.<br><ul><li><strong>Configuration:</strong> You specify a protocol (HTTP/TCP), a path (e.g., <code>/health</code>), a success code (e.g., 200), an interval, and unhealthy/healthy thresholds.</li><li><strong>Behavior:</strong> If a target fails N consecutive checks, the LB marks it 'Unhealthy' and stops routing traffic to it. Once it recovers and passes M checks, it becomes 'Healthy' again automatically.</li></ul>" },
    { q: "What is 'sticky sessions' (session affinity) in a Load Balancer?", a: "<strong>Detailed Solution:</strong> Sticky sessions ensure a user's requests always go to the same backend target for the duration of their session.<br><ul><li><strong>How it works:</strong> The LB sets a special cookie on the user's browser. On subsequent requests, the LB reads the cookie and routes to the same target.</li><li><strong>When to use:</strong> Stateful applications that store session data locally on the server. However, the best practice is stateless architecture — store session data in Redis/DynamoDB so any instance can handle any request.</li></ul>" },
    { q: "What is the difference between an Internet-facing and Internal Load Balancer?", a: "<strong>Detailed Solution:</strong> The distinction is based on whether the LB has a public DNS name resolvable over the internet.<br><ul><li><strong>Internet-facing:</strong> Has public IP addresses. Accessible from the internet. Used for public web applications.</li><li><strong>Internal:</strong> Has only private IP addresses. Only accessible from within the VPC or connected networks. Used for service-to-service communication (e.g., a frontend ALB forwarding to a backend internal ALB).</li></ul>" },
    { q: "What is Cross-Zone Load Balancing?", a: "<strong>Detailed Solution:</strong> Cross-Zone Load Balancing distributes requests evenly across all registered targets in all enabled Availability Zones.<br><ul><li><strong>Without it:</strong> Each LB node only routes traffic to the targets in its own AZ. If AZ-1 has 2 instances and AZ-2 has 8 instances, AZ-1 targets receive 5x more traffic per instance.</li><li><strong>With it:</strong> Every target across all AZs gets an equal share of total traffic regardless of AZ distribution. ALB has cross-zone enabled by default; NLB has it disabled by default (incurs data transfer charges when enabled).</li></ul>" },
    { q: "How does connection draining (deregistration delay) work?", a: "<strong>Detailed Solution:</strong> Connection draining ensures in-flight requests are completed before a target is deregistered or marked unhealthy.<br><ul><li><strong>Behavior:</strong> When you deregister an instance (e.g., during a deployment or scale-in), the LB stops sending NEW requests to it but allows existing in-progress connections up to a configurable timeout (default 300 seconds).</li><li><strong>Result:</strong> Users don't see connection reset errors mid-transaction. After the timeout, the LB forcibly closes remaining connections.</li></ul>" }
  ],
  "Moderate Scenario": [
    { q: "Scenario: Users complain that half the time they get a login error, but refreshing fixes it. The app uses server-side sessions stored in local memory. What is the problem?", a: "<strong>Detailed Solution:</strong> The ALB is round-robining requests between two instances, but only one instance holds the session cookie data.<br><ul><li><strong>Root Cause:</strong> User logs in → Request hits Instance A → Session stored in Instance A's RAM → Next request goes to Instance B → Instance B has no session → Login error.</li><li><strong>Quick Fix:</strong> Enable sticky sessions on the Target Group. The LB will use a cookie to pin the user to Instance A.</li><li><strong>Permanent Fix:</strong> Refactor to stateless architecture. Externalize session storage to Amazon ElastiCache (Redis) or DynamoDB. Any instance can then serve any user's session, enabling full horizontal scaling.</li></ul>" },
    { q: "Scenario: You have one ALB serving two different applications: api.company.com and www.company.com, both on port 443. How do you configure this?", a: "<strong>Detailed Solution:</strong> Use ALB's host-based routing feature.<br><ul><li><strong>Step 1:</strong> Create two Target Groups: TG-API (API EC2 instances) and TG-WWW (Web EC2 instances).</li><li><strong>Step 2:</strong> Create one ALB with a single HTTPS listener on port 443. Attach an ACM wildcard certificate (e.g., <code>*.company.com</code>) or a certificate with both SANs.</li><li><strong>Step 3:</strong> Add two listener rules: Rule 1 — IF Host Header is <code>api.company.com</code>, THEN Forward to TG-API. Rule 2 — IF Host Header is <code>www.company.com</code>, THEN Forward to TG-WWW.</li></ul>" },
    { q: "Scenario: Your LB shows some instances as 'healthy' but users still get 502 Bad Gateway errors. What do you investigate?", a: "<strong>Detailed Solution:</strong> 502 means the LB received an invalid response from the backend. The health check passed (app is alive) but the app is not properly handling requests.<br><ul><li><strong>Check 1:</strong> Is the application process actually running and listening on the expected port? SSH in and run <code>netstat -tlnp | grep PORT</code>.</li><li><strong>Check 2:</strong> Are the Security Group rules on the instances allowing traffic from the LB's security group?</li><li><strong>Check 3:</strong> Are there application-level errors? Check app logs for crashes or OOM errors.</li><li><strong>Check 4:</strong> Is the health check path lenient? Sometimes <code>/health</code> returns 200 but <code>/api/v1/data</code> causes a crash.</li></ul>" },
    { q: "Scenario: You need to redirect all HTTP (port 80) traffic to HTTPS (port 443) at the load balancer level without touching the EC2 instances.", a: "<strong>Detailed Solution:</strong> ALB supports redirect actions natively — no code change needed.<br><ul><li><strong>Step 1:</strong> In the ALB, add a listener on port 80 (HTTP).</li><li><strong>Step 2:</strong> For this listener's default rule, choose 'Redirect' instead of 'Forward'.</li><li><strong>Step 3:</strong> Set the redirect target to HTTPS, port 443, with status code 301 (permanent) or 302 (temporary).</li><li><strong>Result:</strong> Any HTTP request hits the ALB, which immediately issues a redirect response to the browser. No traffic ever reaches the EC2 instances on port 80.</li></ul>" },
    { q: "Scenario: Your application has a /payments microservice that needs stricter SLA. You want to route payment requests to a dedicated, higher-spec group of instances. How?", a: "<strong>Detailed Solution:</strong> Use ALB path-based routing to separate traffic by URL path.<br><ul><li><strong>Step 1:</strong> Create a new Target Group (TG-Payments) with your premium c5.xlarge instances.</li><li><strong>Step 2:</strong> On the ALB's HTTPS listener, add a listener rule with higher priority: IF Path Pattern is <code>/payments*</code>, THEN Forward to TG-Payments.</li><li><strong>Step 3:</strong> The existing default rule continues routing all other traffic to the regular TG-Standard.</li></ul>" },
    { q: "Scenario: After deploying a new version of the app, the LB starts sending traffic to both old and new instances. Users see inconsistent UI. How do you deploy cleanly?", a: "<strong>Detailed Solution:</strong> This is a blue/green deployment problem. The ALB needs to be the switchboard.<br><ul><li><strong>Blue/Green Steps:</strong> 1) Create a new Target Group (Green) with new-version instances. 2) Add the Green TG to the ALB listener at 0% weighted traffic. 3) Perform smoke tests by targeting the Green TG directly. 4) Gradually shift traffic (10% → 50% → 100%) using ALB Weighted Target Groups. 5) Once 100% on Green, deregister and terminate the Blue (old) instances.</li></ul>" },
    { q: "Scenario: You need the load balancer to return a fixed maintenance page (503 status with HTML body) when all targets are unhealthy.", a: "<strong>Detailed Solution:</strong> Use ALB's Fixed Response action.<br><ul><li><strong>Implementation:</strong> In the ALB listener rules, set the default action to 'Return a fixed response'.</li><li><strong>Configuration:</strong> Set Status Code to <code>503</code>, Content-Type to <code>text/html</code>, and the Response Body to your custom maintenance HTML.</li><li><strong>Behavior:</strong> If all targets are unhealthy, the LB returns this static response directly. No request reaches a backend server. This provides a cleaner UX than a browser-level error.</li></ul>" },
    { q: "Scenario: An ALB is receiving millions of requests per second during a flash sale. Response times degrade even though instances seem fine. What could be the bottleneck?", a: "<strong>Detailed Solution:</strong> The ALB itself may be scaling up internally. A sudden massive spike can momentarily overwhelm ALB nodes before they scale.<br><ul><li><strong>Solution 1 (Pre-warming):</strong> Contact AWS Support in advance to request ALB pre-warming before a known flash sale, so it is already at high capacity.</li><li><strong>Solution 2 (NLB):</strong> If extreme performance is needed and content-based routing is not required, place an NLB in front of the ALB. NLB handles millions of req/sec instantly with no warm-up.</li></ul>" },
    { q: "Scenario: You want to authenticate users with Cognito/OIDC before they can access your application backend. Where should this logic live?", a: "<strong>Detailed Solution:</strong> Offload authentication to the ALB, not your application code.<br><ul><li><strong>Feature:</strong> ALB supports built-in authenticate actions in listener rules. Supported providers: Amazon Cognito User Pools and any OIDC-compliant IdP (Google, Okta, etc.).</li><li><strong>How it works:</strong> When an unauthenticated user hits the ALB, the ALB redirects them to the IdP login page. After login, the IdP sends a token back to the ALB, which validates it, then adds user identity headers to the forwarded request.</li><li><strong>Benefit:</strong> Authentication is centralized at the infrastructure layer. Your backend code receives only authenticated requests with user context headers — zero extra code.</li></ul>" },
    { q: "Scenario: You need to expose an internal microservices API (on private IPs) to partner companies over the internet without making instances public.", a: "<strong>Detailed Solution:</strong> Use AWS PrivateLink with an NLB to create a secure, private service endpoint.<br><ul><li><strong>Architecture:</strong> Deploy a Network Load Balancer (NLB) in front of your internal service. Create an 'Endpoint Service' backed by the NLB.</li><li><strong>Partner Access:</strong> The partner company creates a VPC Interface Endpoint in their own VPC that connects to your Endpoint Service.</li><li><strong>Security:</strong> Traffic never leaves the AWS network backbone. Partners get a private IP in their own VPC. You whitelist only approved AWS Account IDs.</li></ul>" }
  ],
  "Advanced Scenario": [
    { q: "Scenario: Design a multi-region active-active architecture for a globally distributed application that uses ALBs in each region.", a: "<strong>Detailed Solution:</strong> Use AWS Global Accelerator or Route 53 with latency-based routing to coordinate multi-region ALBs.<br><ul><li><strong>Component 1: AWS Global Accelerator.</strong> Provides two anycast static IPs that route user traffic to the nearest healthy region's ALB over the AWS backbone. It also handles automatic failover between regions.</li><li><strong>Component 2: Per-Region ALBs.</strong> Each region has its own ALB backed by an ASG. Regional Route 53 health checks monitor ALB health.</li><li><strong>Data Layer:</strong> Use DynamoDB Global Tables or Aurora Global Database with multi-region write forwarding so any region can handle writes.</li></ul>" },
    { q: "Scenario: The security team requires all traffic to be inspected by a stateful firewall (Palo Alto VM) before it reaches your ALB. How do you architect this?", a: "<strong>Detailed Solution:</strong> This is the exact use case for a Gateway Load Balancer (GWLB).<br><ul><li><strong>GWLB Role:</strong> GWLB acts as a transparent bump-in-the-wire. It distributes traffic across a fleet of third-party firewall virtual appliances using the GENEVE protocol.</li><li><strong>Traffic Flow:</strong> Internet → GWLB Endpoint (in your VPC) → GWLB → Palo Alto firewall fleet (in a separate inspection VPC) → back to GWLB → ALB → EC2 instances.</li><li><strong>Key Benefit:</strong> The firewalls can inspect, allow, or drop traffic. GWLB handles HA and scaling of the firewall fleet itself.</li></ul>" },
    { q: "Scenario: An NLB is used for a financial trading platform requiring ultra-low latency. After load testing, you notice the P99 latency is higher than expected. How do you optimize?", a: "<strong>Detailed Solution:</strong> NLB introduces very little overhead, so investigate the full network path.<br><ul><li><strong>Check 1: Cross-Zone LB.</strong> If enabled, NLB incurs cross-AZ data transfer costs AND adds inter-AZ latency. Disable it and ensure traffic routes to the nearest AZ's NLB.</li><li><strong>Check 2: Placement Groups.</strong> Ensure EC2 instances are in a cluster placement group for lowest network latency between them.</li><li><strong>Check 3: Enhanced Networking (ENA/SR-IOV).</strong> Verify instances have ENA enabled — provides lower latency and higher packet-per-second (PPS) performance.</li><li><strong>Check 4: TLS Offload.</strong> Enable NLB TLS termination to offload decryption overhead from the application servers.</li></ul>" },
    { q: "Scenario: You must implement IP whitelisting so that only specific external partner IP ranges can access your ALB. How do you do this efficiently?", a: "<strong>Detailed Solution:</strong> ALB Security Groups support IP-based allow rules, but with many CIDR ranges, use AWS WAF for scalability.<br><ul><li><strong>Method 1 (Small list — Security Group):</strong> Create a Security Group with inbound rules for each allowed IP/CIDR on port 443. Deny all other inbound traffic by not adding a catch-all rule.</li><li><strong>Method 2 (Large list — AWS WAF):</strong> Create a WAF Web ACL. Create an IP Set containing all partner CIDR blocks. Add a WAF rule: 'If source IP is NOT in the IP Set, BLOCK.' Associate the WAF ACL with the ALB. This scales to thousands of IPs without Security Group rule limits.</li></ul>" },
    { q: "Scenario: You need to implement canary deployments where 5% of real production traffic goes to a new code version. Describe the ALB-native approach.", a: "<strong>Detailed Solution:</strong> Use ALB Weighted Target Groups to split live traffic proportionally.<br><ul><li><strong>Setup:</strong> You have TG-Stable (current, weight 95) and TG-Canary (new version, weight 5). Both are targets in the same listener rule.</li><li><strong>Traffic Split:</strong> ALB automatically routes ~95% to stable and ~5% to canary. You monitor CloudWatch metrics for error rates and latency on TG-Canary.</li><li><strong>Progressive Rollout:</strong> If canary looks good, update weights (80/20 → 50/50 → 0/100). If it looks bad, set canary weight to 0 for instant rollback without any deployment.</li></ul>" },
    { q: "Scenario: An ALB is accessed by millions of clients. The security team wants mutual TLS (mTLS) so that only clients with a specific certificate can connect. How?", a: "<strong>Detailed Solution:</strong> ALB supports mTLS natively (mutual TLS).<br><ul><li><strong>Configuration:</strong> In the ALB listener (HTTPS/TLS), enable 'Mutual Authentication'. Upload your trusted CA bundle to ACM or as a trust store in the ALB configuration.</li><li><strong>Behavior:</strong> During the TLS handshake, the ALB requests a client certificate. If the client presents a valid cert signed by your trusted CA, the connection proceeds. The ALB forwards client cert details in headers to the backend application.</li><li><strong>Use case:</strong> B2B integrations, machine-to-machine service calls, zero-trust architectures.</li></ul>" },
    { q: "Scenario: Your company acquires another company. Their app runs on-premise and must be accessible via your AWS ALB. How do you include an on-premise server as a target?", a: "<strong>Detailed Solution:</strong> ALB Target Groups support IP-type targets, allowing any routable IP address, including on-premise.<br><ul><li><strong>Prerequisite:</strong> Network connectivity must exist between AWS and on-premise, via AWS Direct Connect or Site-to-Site VPN.</li><li><strong>Setup:</strong> Create a Target Group with type 'IP'. Register the on-premise server's private IP address as a target. Specify the correct port.</li><li><strong>Result:</strong> The ALB can now route requests to the on-premise server just like an EC2 instance. Health checks work exactly the same way.</li></ul>" },
    { q: "Scenario: You have an ALB fronting a fleet of 200 EC2 instances. The instances are replaced frequently by an ASG. How do you ensure zero-downtime rolling deployments?", a: "<strong>Detailed Solution:</strong> Combine ASG rolling updates with ALB connection draining and lifecycle hooks.<br><ul><li><strong>Connection Draining:</strong> Set the Target Group's deregistration delay to a value greater than your longest expected request duration (e.g., 60 seconds).</li><li><strong>ASG Rolling Update:</strong> Use the ASG 'Instance Refresh' feature with a minimum healthy percentage of 50%. ASG terminates and replaces instances in batches, waiting for new ones to pass health checks before continuing.</li><li><strong>Lifecycle Hook:</strong> Add a 'Terminating:Wait' lifecycle hook. A Lambda function deregisters the instance from the ALB and waits for connection draining to complete before sending 'CONTINUE' to the lifecycle.</li></ul>" },
    { q: "Scenario: An ALB is misconfigured and exposing internal metadata (e.g., debug endpoints). How do you block specific paths at the load balancer level without deploying code?", a: "<strong>Detailed Solution:</strong> Use AWS WAF rules to block requests by URL path pattern at the ALB.<br><ul><li><strong>Step 1:</strong> Create a WAF Web ACL and attach it to the ALB.</li><li><strong>Step 2:</strong> Create a Rule with a 'URI path' string match condition. Use the CONTAINS operator for the sensitive paths (e.g., <code>/debug</code>, <code>/actuator</code>, <code>/admin</code>).</li><li><strong>Step 3:</strong> Set the rule action to BLOCK. WAF immediately returns a 403 response before the request reaches the backend.</li></ul>" },
    { q: "Scenario: You are architecting a real-time gaming backend that requires persistent TCP connections (WebSocket) for thousands of concurrent players. Which LB and why?", a: "<strong>Detailed Solution:</strong> For WebSocket/persistent connections at extreme scale, NLB is the superior choice.<br><ul><li><strong>Why NLB:</strong> NLB works at Layer 4 and doesn't terminate or inspect TCP connections. Once established (including the WebSocket upgrade handshake), NLB maintains the connection for its full duration — which can be hours.</li><li><strong>Setup:</strong> NLB with a TCP listener on port 443. Register game server EC2 instances in the target group. NLB preserves client source IP, which many game backends need for anti-cheat and geo-routing.</li><li><strong>Static IP Benefit:</strong> NLB provides static Elastic IPs per AZ. Game clients can hard-code these IPs, avoiding DNS TTL warmup issues.</li></ul>" }
  ]
};


// ─────────────────────────────────────────────────────────────────────────────
// AWS ▶ ELB (Elastic Load Balancing Deep Dive)
// ─────────────────────────────────────────────────────────────────────────────
window.interviewData["AWS ▶ ELB"] = {
  "Basic": [
    { q: "What is ELB (Elastic Load Balancing) in AWS?", a: "<strong>Detailed Solution:</strong> ELB is the umbrella service name for all AWS managed load balancers.<br><ul><li><strong>Managed service:</strong> AWS provisions, scales, and maintains the load balancer infrastructure. You don't manage servers.</li><li><strong>Family:</strong> ELB includes ALB (Application), NLB (Network), GWLB (Gateway), and CLB (Classic).</li><li><strong>Integration:</strong> Deeply integrated with EC2, ECS, EKS, Lambda, Auto Scaling Groups, ACM (SSL), WAF, CloudWatch, and Route53.</li></ul>" },
    { q: "What is the purpose of an ALB (Application Load Balancer)?", a: "<strong>Detailed Solution:</strong> ALB is a Layer 7 load balancer designed for modern web and microservice architectures.<br><ul><li><strong>Key Features:</strong> Content-based routing (host, path, query string, HTTP headers), native WebSocket support, HTTP/2 support, gRPC support, native authentication via Cognito/OIDC, and AWS WAF integration.</li><li><strong>Best for:</strong> Web applications, REST APIs, microservices, container-based workloads (ECS/EKS).</li></ul>" },
    { q: "What is an NLB (Network Load Balancer) and when should you use it?", a: "<strong>Detailed Solution:</strong> NLB operates at Layer 4 (TCP/UDP/TLS) and is designed for extreme performance.<br><ul><li><strong>Performance:</strong> Handles millions of requests per second with latencies as low as single milliseconds.</li><li><strong>Static IPs:</strong> Provides one static Elastic IP per Availability Zone, which is critical for firewall whitelisting (ALB IPs change).</li><li><strong>Use cases:</strong> Gaming, IoT, financial trading, gRPC, anything requiring static IPs or ultra-low latency, or exposing services via AWS PrivateLink.</li></ul>" },
    { q: "What is SSL/TLS termination at a Load Balancer?", a: "<strong>Detailed Solution:</strong> SSL termination means the LB decrypts HTTPS traffic and forwards plain HTTP to the backend.<br><ul><li><strong>How it works:</strong> You upload your TLS certificate to AWS Certificate Manager (ACM). The LB presents this cert to clients, performs the TLS handshake, and decrypts the data.</li><li><strong>Benefit:</strong> Offloads expensive cryptographic computation from EC2 instances. Centralizes certificate management — renew in ACM once instead of on every server.</li></ul>" },
    { q: "What is SNI (Server Name Indication) and how does ALB use it?", a: "<strong>Detailed Solution:</strong> SNI is a TLS extension that allows a client to specify which hostname it's connecting to during the TLS handshake.<br><ul><li><strong>Problem it solves:</strong> A server with one IP address can host multiple domains with different TLS certificates.</li><li><strong>ALB Usage:</strong> ALB supports SNI, meaning you can attach multiple ACM certificates to a single HTTPS listener. Based on the hostname in the client's TLS ClientHello message, ALB serves the correct certificate — essential for multi-tenant SaaS platforms hosting many customer domains.</li></ul>" },
    { q: "What are the key differences between ALB and Classic Load Balancer (CLB)?", a: "<strong>Detailed Solution:</strong> CLB is the legacy load balancer; ALB is the modern replacement.<br><ul><li><strong>Routing:</strong> CLB routes to instances based on port only. ALB routes based on content (path, host, headers, query strings).</li><li><strong>Targets:</strong> CLB only targets EC2 instances. ALB can target instances, IPs, Lambda, and ECS containers.</li><li><strong>WebSocket/HTTP2:</strong> ALB supports both natively. CLB does not.</li><li><strong>Recommendation:</strong> AWS strongly recommends migrating all CLB workloads to ALB for new features and better performance.</li></ul>" },
    { q: "How does an ELB integrate with Auto Scaling Groups (ASGs)?", a: "<strong>Detailed Solution:</strong> ELB and ASG are deeply coupled for elastic, self-healing architectures.<br><ul><li><strong>Registration:</strong> When an ASG launches a new instance, it automatically registers the instance with the LB's target group. When the ASG terminates an instance, it automatically deregisters it after connection draining completes.</li><li><strong>Health Check Synergy:</strong> You can configure the ASG to use the 'ELB' health check type. If the LB marks an instance unhealthy, the ASG will automatically terminate and replace it — truly self-healing infrastructure.</li></ul>" },
    { q: "What are ALB Access Logs and why are they important?", a: "<strong>Detailed Solution:</strong> ALB access logs capture detailed information about every request served by the load balancer.<br><ul><li><strong>Contents:</strong> Timestamp, client IP, request path, target IP, request processing time, backend response time, response code, user agent, TLS cipher/protocol, target ARN.</li><li><strong>Delivery:</strong> Logs are delivered every 5 minutes to an S3 bucket that you specify.</li><li><strong>Use cases:</strong> Security auditing (who accessed what), debugging 4xx/5xx errors, usage analytics, capacity planning, and forensic investigation after incidents.</li></ul>" },
    { q: "What is the ELB Security Policy for HTTPS listeners?", a: "<strong>Detailed Solution:</strong> The Security Policy is a combination of TLS protocols and cipher suites that the ELB uses when negotiating HTTPS connections.<br><ul><li><strong>Options:</strong> AWS provides predefined policies like <code>ELBSecurityPolicy-TLS13-1-2-2021-06</code> (recommended — supports TLS 1.2 and 1.3 only) and legacy ones supporting TLS 1.0 for older clients.</li><li><strong>Best Practice:</strong> Use the latest policy that supports TLS 1.3 and disables older, vulnerable TLS versions (1.0, 1.1) and weak cipher suites to meet PCI-DSS and SOC2 compliance requirements.</li></ul>" },
    { q: "How does AWS WAF integrate with ALB?", a: "<strong>Detailed Solution:</strong> AWS WAF (Web Application Firewall) inspects HTTP/HTTPS traffic at the ALB before it reaches your application.<br><ul><li><strong>Protection:</strong> WAF can block OWASP Top 10 attacks: SQL injection, XSS (Cross-Site Scripting), Remote Code Execution, bad bots, IP reputation lists, and geographic restrictions.</li><li><strong>Managed Rules:</strong> AWS and AWS Marketplace vendors offer pre-built managed rule groups that you can enable with one click.</li><li><strong>Association:</strong> Attach a WAF Web ACL to an ALB in the same region. WAF processes every request through the rule set before forwarding to the target group.</li></ul>" }
  ],
  "Moderate Scenario": [
    { q: "Scenario: Your ALB access logs show a flood of requests from 50 different IPs targeting /login with POST. This is a credential stuffing attack. How do you respond?", a: "<strong>Detailed Solution:</strong> Implement a multi-layered WAF response.<br><ul><li><strong>Step 1 (Immediate):</strong> Create a WAF IP Set with all 50 attacker IPs. Create a WAF rule to BLOCK all traffic from this IP set. Apply to the ALB's Web ACL.</li><li><strong>Step 2 (Short-term):</strong> Enable WAF Rate Limiting Rule on the <code>/login</code> path — e.g., block any IP making more than 100 requests per 5 minutes to that path.</li><li><strong>Step 3 (Long-term):</strong> Enable AWS WAF Bot Control managed rule group to detect and block bot traffic automatically. Enable CAPTCHA challenges for the login endpoint.</li></ul>" },
    { q: "Scenario: An ALB with 20 registered instances is under-utilizing 18 of them — all traffic goes to 2 instances. What could cause this?", a: "<strong>Detailed Solution:</strong> DNS caching is causing clients to resolve to old ALB node IPs, which then map to only 2 instances.<br><ul><li><strong>Root Cause:</strong> ALB has multiple IP addresses. If a client or upstream proxy caches the DNS resolution for too long, they always hit the same ALB node, which may map to the same backend targets.</li><li><strong>Fix 1:</strong> Ensure clients respect the ALB's DNS TTL (typically 60 seconds). Check if any intermediary proxy is caching DNS and configure it to re-resolve periodically.</li><li><strong>Fix 2:</strong> Verify Cross-Zone Load Balancing is enabled. If a single ALB node in one AZ gets all external traffic, Cross-Zone LB ensures it distributes to instances in ALL AZs.</li></ul>" },
    { q: "Scenario: You are migrating from CLB to ALB. What steps do you take to ensure zero downtime?", a: "<strong>Detailed Solution:</strong> Run CLB and ALB in parallel and gradually shift DNS traffic.<br><ul><li><strong>Step 1:</strong> Create the new ALB with the same target instances/ASG as the CLB. Configure identical listener rules, security groups, and certificates.</li><li><strong>Step 2:</strong> Test the ALB DNS name directly (not via Route53) to verify it functions correctly.</li><li><strong>Step 3:</strong> In Route53, create a weighted routing policy: CLB at 90%, ALB at 10%. Monitor error rates in CloudWatch.</li><li><strong>Step 4:</strong> Gradually shift to 50/50, then 0/100. Once stable, update DNS to the ALB only, then delete the CLB.</li></ul>" },
    { q: "Scenario: You need the ALB to pass the real client IP to the backend application, but the app sees the ALB IP instead. How do you fix this?", a: "<strong>Detailed Solution:</strong> The ALB adds the client's real IP in the <code>X-Forwarded-For</code> HTTP header.<br><ul><li><strong>ALB Behavior:</strong> When ALB forwards a request to a backend, it uses its own IP as the TCP source. The original client IP is preserved in the <code>X-Forwarded-For</code> header.</li><li><strong>Application Fix:</strong> Configure your web application (Nginx, Apache, Spring Boot, etc.) to read the real IP from the <code>X-Forwarded-For</code> header instead of the TCP source IP (<code>REMOTE_ADDR</code>).</li><li><strong>NLB Difference:</strong> NLB preserves the original source IP at the TCP level, so the app sees the client IP directly without needing special headers.</li></ul>" },
    { q: "Scenario: Your team wants to test if ELB can handle peak load of 100,000 req/sec before the product launch. How do you approach this?", a: "<strong>Detailed Solution:</strong> Pre-warm the ALB and use a realistic load test approach.<br><ul><li><strong>Step 1 (Contact AWS):</strong> Submit an AWS Support ticket requesting ALB pre-warming if the test will send a sudden traffic spike. Provide the load test dates, expected RPS, and average request/response size.</li><li><strong>Step 2 (Ramp-up):</strong> Instead of a sudden spike, ramp traffic up gradually over 5-10 minutes. This allows the ALB to auto-scale its internal capacity organically.</li><li><strong>Step 3 (Load Testing Tool):</strong> Use tools like Apache JMeter, Gatling, Locust, or AWS Distributed Load Testing solution. Distribute load generators across multiple AZs.</li></ul>" },
    { q: "Scenario: ELB health checks are randomly failing even though the app works fine for real users. Investigate.", a: "<strong>Detailed Solution:</strong> Health check failures that don't correlate with user impact often point to health check misconfiguration.<br><ul><li><strong>Check 1: Path:</strong> Does the health check path (<code>/health</code>) actually exist and return 200? Some apps return 301 redirects or require authentication on that path — both cause health check failure.</li><li><strong>Check 2: Thresholds:</strong> If the app takes 3 seconds to respond but the timeout is 2 seconds — intermittent timeouts will cause flapping. Increase the timeout.</li><li><strong>Check 3: Security Group:</strong> Ensure the EC2 Security Group allows inbound traffic on the health check port from the ALB's Security Group.</li></ul>" },
    { q: "Scenario: You want to implement a multi-tenant SaaS where each customer gets their own subdomain all pointing to the same ALB. How do you route correctly?", a: "<strong>Detailed Solution:</strong> Use ALB Host-Based routing with a wildcard certificate.<br><ul><li><strong>Certificate:</strong> Issue a wildcard ACM certificate for <code>*.saas.com</code>. Attach it to the ALB HTTPS listener. ALB uses SNI to serve this certificate for any <code>*.saas.com</code> request.</li><li><strong>Routing:</strong> Use a single listener rule with pattern <code>*.saas.com</code> forwarding to a target group. Your application extracts the subdomain from the <code>Host</code> header to identify the tenant and serve the correct data.</li></ul>" },
    { q: "Scenario: Cost Analysis shows ELB data processing charges are very high. How can you reduce them?", a: "<strong>Detailed Solution:</strong> ELB charges are based on LCUs (Load Balancer Capacity Units), which factor in connections, requests, bandwidth, and rule evaluations.<br><ul><li><strong>Optimization 1: Enable compression.</strong> Ensure your application compresses responses with gzip/Brotli. This reduces the bytes processed through the LB.</li><li><strong>Optimization 2: Reduce rule complexity.</strong> Simplify listener rules — complex regex rules or many rules cost more LCU evaluation units.</li><li><strong>Optimization 3: Move static assets to CloudFront+S3.</strong> Static files (images, JS, CSS) should be served by CloudFront, not through the ALB. This eliminates LB data processing charges for static content entirely.</li></ul>" },
    { q: "Scenario: You have an ALB in us-east-1. Users in Asia complain about slow response times. How do you improve latency without changing the ALB region?", a: "<strong>Detailed Solution:</strong> Add AWS CloudFront in front of the ALB as a CDN layer for cacheable content.<br><ul><li><strong>Step 1:</strong> Create a CloudFront distribution with the ALB DNS name as the origin.</li><li><strong>Step 2:</strong> Set caching behavior: Cache <code>GET</code> responses for static/API paths with appropriate TTLs. Set <code>POST</code>/<code>PUT</code> to no-cache (pass-through to ALB).</li><li><strong>Step 3:</strong> Asian users now hit the nearest CloudFront edge location. Cached responses are served instantly. Only uncacheable requests travel the full path to us-east-1.</li></ul>" },
    { q: "Scenario: Your company is processing HIPAA-regulated health data. What ELB configurations are required for compliance?", a: "<strong>Detailed Solution:</strong> HIPAA requires encryption in transit and at rest, access controls, and audit logging.<br><ul><li><strong>Encryption in Transit:</strong> Enforce HTTPS only. Add an HTTP to HTTPS redirect on the port 80 listener. Use the latest TLS security policy (TLS 1.2+ minimum) on the HTTPS listener.</li><li><strong>Access Logging:</strong> Enable ELB access logs to an S3 bucket with AES-256 server-side encryption. Retain logs for minimum 6 years per HIPAA requirements.</li><li><strong>WAF:</strong> Attach AWS WAF to prevent common application attacks that could lead to PHI exposure.</li><li><strong>Business Associate Agreement:</strong> Ensure you have an active BAA with AWS — this is a legal requirement. ELB is a HIPAA-eligible service.</li></ul>" }
  ],
  "Advanced Scenario": [
    { q: "Scenario: You need zero-downtime certificate rotation on an ALB serving 10,000 concurrent users. How do you execute this?", a: "<strong>Detailed Solution:</strong> Use ACM for automatic certificate management to make this completely transparent.<br><ul><li><strong>Best Path (ACM Managed):</strong> Issue/import the certificate in ACM. Attach it to the ALB listener. ACM automatically renews certificates 60 days before expiry and applies the new certificate to the ALB with zero downtime, no user disruption.</li><li><strong>Manual Rotation:</strong> If using an external cert, upload the new certificate to ACM (import). In the ALB listener, update the 'default certificate' to the new one. During the update, ALB uses the new cert for new TLS handshakes while existing connections use the old cert until they complete. Zero connection drops.</li></ul>" },
    { q: "Scenario: You must implement a global load balancing strategy that routes users to the nearest healthy region and automatically fails over if one region's ELB is unhealthy.", a: "<strong>Detailed Solution:</strong> Use AWS Global Accelerator (not Route53) for deterministic sub-minute failover.<br><ul><li><strong>Why not Route53:</strong> Route53 DNS failover can take minutes due to DNS TTL caching at ISPs. Global Accelerator reroutes at the network layer in under 30 seconds.</li><li><strong>Setup:</strong> Create a Global Accelerator. Add two endpoints (e.g., ALB in us-east-1 and eu-west-1). Configure endpoint health checks. Assign traffic dial percentages (e.g., 50/50).</li><li><strong>Failover:</strong> Global Accelerator detects that us-east-1's ALB is unhealthy and instantly routes 100% of traffic to eu-west-1's ALB. Users' anycast IP doesn't change, so no DNS cache issues.</li></ul>" },
    { q: "Scenario: Design an ELB architecture for a containerized microservices platform on ECS where each microservice has independent scaling and routing rules.", a: "<strong>Detailed Solution:</strong> One ALB serves as the ingress for all microservices using path-based routing to independent target groups.<br><ul><li><strong>Pattern:</strong> Deploy ECS services (user-service, order-service, payment-service). Each registers with its own ALB Target Group using dynamic port mapping.</li><li><strong>ALB Rules:</strong> <code>/api/users*</code> → TG-UserService. <code>/api/orders*</code> → TG-OrderService. <code>/api/payments*</code> → TG-PaymentService.</li><li><strong>Scaling:</strong> Each ECS service has its own Application Auto Scaling policy based on ALB RequestCountPerTarget metric from its specific target group.</li></ul>" },
    { q: "Scenario: An ALB access log reveals a specific backend instance takes 30 seconds to respond to certain requests, causing ALB 504 Gateway Timeout errors. Diagnose and fix.", a: "<strong>Detailed Solution:</strong> Systematic triage from ALB timeout configuration to application bottleneck.<br><ul><li><strong>Step 1: Check ALB Idle Timeout.</strong> ALB's default idle timeout is 60 seconds. If the app legitimately needs more time, increase it in ALB settings.</li><li><strong>Step 2: Identify the instance.</strong> Parse access logs for the target IP/port showing high <code>target_processing_time</code>. SSH into that specific instance.</li><li><strong>Step 3: Diagnose the app.</strong> On the instance, use <code>htop</code>, <code>iostat</code>, and thread/heap dumps to find the bottleneck — CPU saturation, I/O block on a slow database query, or a synchronous blocking call to a downstream service.</li></ul>" },
    { q: "Scenario: You want to implement rate limiting at the ELB level so that any single IP cannot make more than 1000 requests per minute to your API.", a: "<strong>Detailed Solution:</strong> ELB doesn't natively rate limit; use AWS WAF's rate-based rules.<br><ul><li><strong>Step 1:</strong> Attach a WAF Web ACL to the ALB.</li><li><strong>Step 2:</strong> Create a Rate-based Rule in WAF. Set the rate limit to 1000 requests per 5-minute window (WAF uses 5-minute windows). Set the key to 'Source IP'.</li><li><strong>Step 3:</strong> Set the action to BLOCK. Any IP exceeding the threshold gets a 403 blocked response automatically until their rate drops below the threshold.</li><li><strong>Advanced:</strong> Use WAF Captcha action instead of Block for browser clients — shows a challenge page, filtering bots while allowing legitimate users who solve it.</li></ul>" },
    { q: "Scenario: You are running an ALB and need to implement a circuit breaker pattern so the LB stops sending requests to a degraded service automatically.", a: "<strong>Detailed Solution:</strong> ALB health checks combined with Target Group anomaly detection provide LB-level circuit breaking.<br><ul><li><strong>Health Check Tuning:</strong> Set the health check interval to 10 seconds and unhealthy threshold to 2. A target that fails 2 checks in 20 seconds is deregistered. This is the LB's native circuit breaker — it 'opens the circuit' to that instance.</li><li><strong>Target Group Level:</strong> If ALL targets are unhealthy (circuit fully open), configure the listener's default action to return a fixed 503 response — preventing traffic from queuing and cascading failures.</li><li><strong>Application-Level:</strong> For more sophisticated circuit breaking, implement it in the application using a library like Resilience4j (Java) or use AWS App Mesh with Envoy proxy's circuit breaker configuration.</li></ul>" },
    { q: "Scenario: An enterprise wants to enforce that only requests originating from their AWS Organization's accounts can access the internal ALB. How do you implement this?", a: "<strong>Detailed Solution:</strong> Combine AWS Resource Policies, VPC Endpoint Policies, and WAF for org-level access control.<br><ul><li><strong>Method 1 (VPC Endpoint + Policy):</strong> Deploy the ALB as an internal LB. Create a VPC Endpoint Service. Create a resource policy on the endpoint allowing only principals from the AWS Organization (using <code>aws:PrincipalOrgID</code> condition in the policy). Partner accounts create endpoints to access the service.</li><li><strong>Method 2 (IAM Authorization):</strong> Use the ALB's OIDC/Cognito authentication feature integrated with AWS SSO. Only users from the corporate identity provider can authenticate and access the ALB.</li></ul>" },
    { q: "Scenario: You have a bi-directional streaming gRPC application that needs load balancing. Standard ALB/NLB setup doesn't work well. Why, and what is the solution?", a: "<strong>Detailed Solution:</strong> gRPC uses HTTP/2 multiplexing, which creates long-lived connections — problematic for LB distribution.<br><ul><li><strong>The Problem:</strong> HTTP/2 multiplexes multiple streams over one TCP connection. An NLB routes the connection to one backend instance. All gRPC streams over that connection go to the same server — no per-stream distribution.</li><li><strong>ALB Solution:</strong> ALB supports gRPC natively with HTTP/2. It routes at the stream (Layer 7) level, distributing individual gRPC requests across backend instances rather than per-connection. Create a target group with protocol 'gRPC' and configure health checks with gRPC health probe.</li></ul>" },
    { q: "Scenario: Post-mortem of an outage reveals the ALB in a single AZ failed, taking down the entire service, despite instances in 2 AZs. What went wrong and how do you fix it?", a: "<strong>Detailed Solution:</strong> The ALB was configured for a single AZ instead of multi-AZ.<br><ul><li><strong>Root Cause:</strong> An ALB must be deployed to subnets in at least two AZs. If only one AZ's subnet was selected during creation, the ALB has no redundancy. If that AZ suffers a failure, the ALB is gone.</li><li><strong>Fix:</strong> Modify the ALB to add a public subnet from the second AZ. AWS provisions ALB nodes in both AZs automatically.</li><li><strong>Verification:</strong> The ALB DNS name should resolve to multiple IPs — one per AZ. Verify with <code>nslookup alb-dns-name</code> — you should see 2+ IPs in response.</li></ul>" },
    { q: "Scenario: You want to implement request tracing end-to-end (from client to ALB to microservices) for distributed debugging. How do you set this up with ALB?", a: "<strong>Detailed Solution:</strong> Use ALB's X-Amzn-Trace-Id header combined with AWS X-Ray for end-to-end distributed tracing.<br><ul><li><strong>ALB Behavior:</strong> The ALB automatically adds an <code>X-Amzn-Trace-Id</code> header to every forwarded request. This header contains a unique trace ID.</li><li><strong>X-Ray Integration:</strong> Instrument your application code with the AWS X-Ray SDK. The SDK reads the trace ID from the header and creates child segments for each operation (DB query, downstream API call).</li><li><strong>Visualization:</strong> In the AWS X-Ray console, view the service map showing the complete request trace: client → ALB → service A → DB, including timing, errors, and throttles at each segment.</li></ul>" }
  ]
};


// ─────────────────────────────────────────────────────────────────────────────
// AWS ▶ S3
// ─────────────────────────────────────────────────────────────────────────────
window.interviewData["AWS ▶ S3"] = {
  "Basic": [
    { q: "What is Amazon S3 and what are its core use cases?", a: "<strong>Detailed Solution:</strong> Amazon Simple Storage Service (S3) is an object storage service offering industry-leading scalability, data availability, security, and performance.<br><ul><li><strong>Core Characteristics:</strong> Objects (files + metadata) are stored in buckets. Each object can be up to 5 TB. Buckets are globally unique in name but exist in a specific region. S3 is designed for 99.999999999% (11 nines) durability.</li><li><strong>Use Cases:</strong> Static website hosting, data lake storage, backup and archival, media distribution via CloudFront CDN, application data storage, log aggregation, ML training data, and disaster recovery.</li></ul>" },
    { q: "What is an S3 Bucket and what naming rules apply?", a: "<strong>Detailed Solution:</strong> An S3 bucket is a container for objects (files) in S3.<br><ul><li><strong>Naming Rules:</strong> Must be globally unique across ALL AWS accounts worldwide. Must be 3-63 characters. Only lowercase letters, numbers, and hyphens. Cannot be formatted as an IP address. Cannot start or end with a hyphen.</li><li><strong>Region:</strong> Buckets reside in one AWS region. The bucket name must be globally unique because S3 bucket URLs take the form <code>bucket-name.s3.amazonaws.com</code>, which is global.</li></ul>" },
    { q: "What are S3 Storage Classes and how do they differ?", a: "<strong>Detailed Solution:</strong> S3 Storage Classes allow you to balance cost vs. retrieval speed based on access patterns.<br><ul><li><strong>S3 Standard:</strong> Frequently accessed data. Low latency, high throughput. Most expensive.</li><li><strong>S3 Standard-IA (Infrequent Access):</strong> Data accessed less than once per month. Lower storage cost, per-retrieval fee.</li><li><strong>S3 One Zone-IA:</strong> Same as Standard-IA but stored in a single AZ. 20% cheaper, less resilient.</li><li><strong>S3 Glacier Instant Retrieval:</strong> Archive data with millisecond retrieval. Very low storage cost.</li><li><strong>S3 Glacier Flexible/Deep Archive:</strong> Long-term archival (years). Cheapest. Retrieval takes minutes to hours.</li><li><strong>S3 Intelligent-Tiering:</strong> Auto-moves objects between tiers based on access patterns.</li></ul>" },
    { q: "What is an S3 Bucket Policy vs. an S3 ACL (Access Control List)?", a: "<strong>Detailed Solution:</strong> Both control access to S3 resources but at different granularities.<br><ul><li><strong>Bucket Policy:</strong> A JSON-based resource policy attached to the bucket. Controls access at the bucket and object level. Supports conditions (IP, VPC, MFA). Recommended for most use cases.</li><li><strong>S3 ACL:</strong> A legacy, per-object or per-bucket access control mechanism using predefined grants (READ, WRITE). Limited expressiveness. AWS recommends disabling ACLs (enable 'Object Ownership = Bucket Owner Enforced') and using bucket policies instead.</li></ul>" },
    { q: "What is S3 Versioning and why is it important?", a: "<strong>Detailed Solution:</strong> S3 Versioning keeps multiple variants of an object in the same bucket.<br><ul><li><strong>How it works:</strong> Every time you upload an object, S3 creates a new version with a unique version ID. Previous versions are retained. Even a deletion creates a 'delete marker' rather than permanent removal.</li><li><strong>Benefits:</strong> Protects against accidental deletion or overwrite. Enables easy rollback to previous object versions. Required for S3 Object Lock and Cross-Region Replication with delete markers.</li><li><strong>Cost:</strong> All versions consume storage space. Use S3 Lifecycle Rules to expire old versions automatically.</li></ul>" },
    { q: "What is S3 Server-Side Encryption (SSE) and what are the types?", a: "<strong>Detailed Solution:</strong> SSE encrypts objects at rest within S3.<br><ul><li><strong>SSE-S3 (Default):</strong> AWS manages the encryption keys using AES-256. Simplest option — no customer key management needed.</li><li><strong>SSE-KMS:</strong> AWS Key Management Service (KMS) manages the keys. You get full audit trails in CloudTrail for every decrypt operation. Required for compliance (HIPAA, PCI-DSS).</li><li><strong>SSE-C (Customer Provided Keys):</strong> You provide and manage your own encryption key with each request. AWS performs the encryption/decryption but never stores your key.</li><li><strong>Default Encryption:</strong> You can enable a default encryption setting on a bucket so all new objects are encrypted automatically.</li></ul>" },
    { q: "What is S3 Transfer Acceleration?", a: "<strong>Detailed Solution:</strong> S3 Transfer Acceleration speeds up long-distance file transfers using AWS CloudFront's globally distributed edge locations.<br><ul><li><strong>How it works:</strong> Instead of uploading directly to S3 in the origin region, the data goes to the nearest CloudFront edge location over HTTP. CloudFront then transfers it to S3 over the optimized AWS backbone network.</li><li><strong>When to use:</strong> Useful when your users are geographically distributed globally. Can improve upload speed by 50-500%.</li></ul>" },
    { q: "What is an S3 Pre-Signed URL?", a: "<strong>Detailed Solution:</strong> A Pre-Signed URL grants temporary access to a private S3 object to any bearer of the URL without requiring AWS credentials.<br><ul><li><strong>How it works:</strong> An IAM principal with permission to the object generates a pre-signed URL using the AWS SDK/CLI. The URL contains an embedded signature, expiry time, bucket, and object key.</li><li><strong>Use case:</strong> Your S3 bucket is private. A user needs to download a specific file. Your backend generates a pre-signed URL valid for 15 minutes. The user downloads via the URL — no AWS account needed. Also used for pre-signed PUT URLs to allow direct browser-to-S3 uploads.</li></ul>" },
    { q: "What is S3 Cross-Region Replication (CRR)?", a: "<strong>Detailed Solution:</strong> CRR automatically copies objects from a source bucket in one AWS region to a destination bucket in a different region.<br><ul><li><strong>Prerequisites:</strong> Versioning must be enabled on both source and destination buckets. An IAM role with permissions to replicate must be created.</li><li><strong>Use cases:</strong> Disaster recovery (data in two geographic locations), compliance (data residency requirements), latency reduction (serve objects from a region closer to users), cross-account data sharing.</li><li><strong>Note:</strong> Replication is asynchronous and eventual. Existing objects are NOT replicated automatically — only new objects after CRR is enabled.</li></ul>" },
    { q: "What is the S3 Block Public Access feature?", a: "<strong>Detailed Solution:</strong> Block Public Access is a set of account-level and bucket-level settings that prevent accidental public exposure of S3 data.<br><ul><li><strong>Settings:</strong> BlockPublicAcls, IgnorePublicAcls, BlockPublicPolicy, RestrictPublicBuckets. Enabling all four ensures no bucket policy or ACL can make objects publicly accessible.</li><li><strong>Default:</strong> Since 2023, new AWS accounts have Block Public Access enabled by default at the account level. This prevents S3 data breaches from misconfiguration — a leading cause of cloud security incidents.</li></ul>" }
  ],
  "Moderate Scenario": [
    { q: "Scenario: A developer accidentally deleted a critical file from S3. How do you recover it?", a: "<strong>Detailed Solution:</strong> Recovery depends on whether versioning was enabled.<br><ul><li><strong>If Versioning Enabled:</strong> Deletion creates a 'Delete Marker' but does not remove versions. List object versions using <code>aws s3api list-object-versions --bucket BUCKET --prefix KEY</code>. Find the version ID from before deletion. Copy that version back or delete the delete marker to restore it.</li><li><strong>If Versioning NOT Enabled:</strong> The object is permanently gone. You can only restore from external backups. This is why enabling versioning on critical buckets is non-negotiable.</li></ul>" },
    { q: "Scenario: A security audit finds that 30% of S3 buckets across the company are publicly accessible. How do you remediate at scale?", a: "<strong>Detailed Solution:</strong> Apply S3 Block Public Access at the organization/account level and enforce via SCP.<br><ul><li><strong>Immediate Fix:</strong> In the S3 Console, turn on Block Public Access for the entire AWS account. This overrides all bucket-level settings and ACLs, making all buckets private instantly.</li><li><strong>Preventative (AWS Organizations SCP):</strong> Create a Service Control Policy that denies <code>s3:PutBucketPublicAccessBlock</code> when the block setting is false. This prevents any account in the org from disabling public access blocks.</li><li><strong>Detection:</strong> Use AWS Config rule <code>s3-bucket-public-read-prohibited</code> to continuously detect and alert on public buckets.</li></ul>" },
    { q: "Scenario: Users upload large video files (5 GB+) to S3 via your web app. The uploads frequently time out or fail midway. How do you solve this?", a: "<strong>Detailed Solution:</strong> Use S3 Multipart Upload for large objects.<br><ul><li><strong>Multipart Upload:</strong> Splits the file into parts (minimum 5 MB each). Each part is uploaded independently and can be retried individually on failure. Parts are uploaded in parallel for maximum throughput.</li><li><strong>Implementation:</strong> Use the AWS SDK's <code>upload()</code> method (high-level API) in Python (boto3), Java, or JavaScript — it handles multipart automatically for files over 8 MB.</li><li><strong>Cleanup:</strong> Configure a lifecycle rule to abort incomplete multipart uploads after 7 days to prevent accumulating storage costs from abandoned uploads.</li></ul>" },
    { q: "Scenario: An S3 bucket must only be accessible from within a specific VPC. No public internet access should be allowed. How do you configure this?", a: "<strong>Detailed Solution:</strong> Use a VPC Gateway Endpoint for S3 combined with a restrictive bucket policy.<br><ul><li><strong>Step 1 (VPC Endpoint):</strong> Create a VPC Gateway Endpoint for S3 in the target VPC. Update route tables to route S3 traffic through the endpoint.</li><li><strong>Step 2 (Bucket Policy):</strong> Add a bucket policy DENY condition: Deny all principals UNLESS <code>aws:sourceVpce</code> equals the specific VPC Endpoint ID. This ensures even if an IAM user has S3 permissions, they can only access the bucket from within the VPC.</li><li><strong>Step 3:</strong> Enable Block Public Access on the bucket to prevent accidental public access overrides.</li></ul>" },
    { q: "Scenario: Your application generates millions of temporary files in S3 (session logs, temp exports). Storage costs are ballooning. How do you automate cleanup?", a: "<strong>Detailed Solution:</strong> Use S3 Lifecycle Policies to automatically transition or delete objects based on age.<br><ul><li><strong>Implementation:</strong> Create a lifecycle rule on the bucket (or a specific prefix like <code>/temp/</code>). Rule: After 1 day — Move to S3 Standard-IA. After 7 days — Delete permanently.</li><li><strong>For Versioned Buckets:</strong> Add additional lifecycle rules: Expire non-current object versions after 30 days. Abort incomplete multipart uploads after 7 days.</li><li><strong>Monitoring:</strong> Use S3 Storage Lens to visualize storage trends by bucket, prefix, and storage class. Set cost alerts in AWS Budgets.</li></ul>" },
    { q: "Scenario: You need to analyze 10 TB of log files stored in S3 without downloading them or running an EC2 instance. How do you query the data?", a: "<strong>Detailed Solution:</strong> Use Amazon Athena to run SQL queries directly on S3 data (serverless).<br><ul><li><strong>Setup:</strong> Create an Athena database and table pointing to the S3 prefix where logs are stored. Define the schema and specify the SerDe (serializer/deserializer) for your log format (JSON, CSV, Parquet, etc.).</li><li><strong>Query:</strong> Run standard SQL: <code>SELECT ip, COUNT(*) FROM logs WHERE status=500 GROUP BY ip ORDER BY 2 DESC LIMIT 10;</code></li><li><strong>Optimization:</strong> Convert logs to Parquet/ORC columnar format and partition by date. Athena scans only the partitions needed, drastically reducing cost (charged per TB scanned).</li></ul>" },
    { q: "Scenario: Compliance requires that specific S3 objects (legal documents) cannot be deleted or modified for 7 years. How do you enforce this?", a: "<strong>Detailed Solution:</strong> Use S3 Object Lock with WORM (Write Once, Read Many) enforcement.<br><ul><li><strong>Prerequisites:</strong> Versioning must be enabled. Object Lock must be enabled at bucket creation (cannot be enabled later).</li><li><strong>Retention Mode:</strong> COMPLIANCE mode — no one, not even the root account, can delete or modify the locked object before the retention period expires. GOVERNANCE mode — privileged users can override with <code>s3:BypassGovernanceRetention</code> permission.</li><li><strong>Legal Hold:</strong> Apply a Legal Hold on specific objects — they cannot be deleted until the legal hold is explicitly removed, regardless of retention period.</li></ul>" },
    { q: "Scenario: You want to host a React SPA (Single Page Application) on S3 with a custom domain and HTTPS, at minimal cost.", a: "<strong>Detailed Solution:</strong> Combine S3 static hosting, CloudFront, ACM, and Route53.<br><ul><li><strong>Step 1 (S3):</strong> Create an S3 bucket. Upload React build files. Enable Static Website Hosting (index document: <code>index.html</code>, error document: <code>index.html</code> for SPA routing).</li><li><strong>Step 2 (CloudFront):</strong> Create a CloudFront distribution. Set origin to the S3 website endpoint. Configure OAC (Origin Access Control) — deny public S3 access, only CloudFront can read it. Set custom error responses: 404 to <code>/index.html</code> with 200 status (for client-side routing).</li><li><strong>Step 3 (HTTPS + Domain):</strong> Issue a free ACM certificate (must be in us-east-1 for CloudFront). Attach it to the CloudFront distribution. Create Route53 A record (alias) pointing to the CloudFront domain.</li></ul>" },
    { q: "Scenario: Your team needs to audit who accessed which S3 objects over the last 30 days for a security investigation.", a: "<strong>Detailed Solution:</strong> Enable S3 Server Access Logging and/or use AWS CloudTrail.<br><ul><li><strong>S3 Server Access Logs:</strong> Enable on the bucket. Logs are delivered to a separate bucket. Each log entry includes requester IP, request time, HTTP status, object key, bytes transferred. Query with Athena.</li><li><strong>CloudTrail Data Events:</strong> Enable CloudTrail data event logging for S3. This captures every GetObject, PutObject, DeleteObject API call with the IAM principal, source IP, and timestamp.</li><li><strong>Query:</strong> Use Athena on CloudTrail logs: <code>SELECT userIdentity.arn, requestParameters.key FROM cloudtrail_logs WHERE eventsource='s3.amazonaws.com' AND eventname='GetObject';</code></li></ul>" },
    { q: "Scenario: An application must process files immediately when they are uploaded to S3. How do you build this event-driven pipeline?", a: "<strong>Detailed Solution:</strong> Use S3 Event Notifications to trigger downstream processing automatically.<br><ul><li><strong>Trigger:</strong> Configure S3 Event Notifications on the bucket for the <code>s3:ObjectCreated:*</code> event type. Filter by prefix (<code>/uploads/</code>) and suffix (<code>.csv</code>) to avoid triggering on unrelated objects.</li><li><strong>Target Options:</strong> SNS (fan out to multiple processors), SQS (queue for decoupled processing, handles back-pressure), Lambda (serverless processing, code runs directly on upload).</li><li><strong>Architecture Example:</strong> S3 to SQS to Lambda to DynamoDB. SQS buffers events during traffic spikes. Lambda polls SQS and processes each file. Failed files go to an SQS Dead Letter Queue (DLQ) for manual review.</li></ul>" }
  ],
  "Advanced Scenario": [
    { q: "Scenario: Design a PB-scale data lake on S3 with governance, cataloging, and query capabilities for 50 data science teams.", a: "<strong>Detailed Solution:</strong> Combine S3 with AWS Lake Formation for a governed, enterprise data lake.<br><ul><li><strong>Storage Layer:</strong> Single S3 bucket per environment (raw, processed, curated zones). Use a standard prefix structure: <code>s3://lake/domain/dataset/year=YYYY/month=MM/day=DD/</code>. Convert raw data to columnar Parquet/ORC format in the curated zone.</li><li><strong>Cataloging:</strong> Use AWS Glue Data Catalog as the central metadata store. Glue Crawlers auto-discover and catalog new S3 data.</li><li><strong>Governance (Lake Formation):</strong> Define data lake permissions in Lake Formation. Grant column-level, row-level access to Glue tables — data scientist team A can query user_id but not pii_data columns.</li><li><strong>Query:</strong> Teams use Athena (SQL), EMR (Spark/Hive), or SageMaker (ML) to query the data lake through the Glue catalog.</li></ul>" },
    { q: "Scenario: S3 costs for a bucket have tripled in 30 days. How do you diagnose and reduce the cost?", a: "<strong>Detailed Solution:</strong> Use S3 Storage Lens and Cost Explorer for root cause analysis.<br><ul><li><strong>Step 1 (Identify):</strong> Use S3 Storage Lens dashboard to see which buckets, prefixes, or storage classes are growing fastest. Check Cost Explorer with S3 as the service, grouped by usage type (Storage, Requests, Data Transfer).</li><li><strong>Step 2 (Common Causes):</strong> Versioning enabled but no lifecycle rule expiring old versions. Incomplete multipart uploads accumulating. Data Transfer Out charges from objects being served without CloudFront.</li><li><strong>Step 3 (Remediation):</strong> Add lifecycle rules to expire non-current versions. Abort incomplete multipart uploads. Enable CloudFront in front of S3. Enable S3 Intelligent-Tiering for data with unpredictable access patterns.</li></ul>" },
    { q: "Scenario: You need to build a multi-region active-active S3 architecture where writes in any region are replicated to all other regions within seconds.", a: "<strong>Detailed Solution:</strong> Use S3 Multi-Region Access Points with replication.<br><ul><li><strong>S3 Multi-Region Access Point (MRAP):</strong> A global endpoint that routes requests to the S3 bucket in the nearest AWS region with the lowest latency. Supports read and write operations.</li><li><strong>Replication:</strong> Configure bidirectional S3 Cross-Region Replication between all regional buckets. Enable S3 Replication Time Control (RTC) for 99.99% of objects to be replicated within 15 minutes.</li><li><strong>Failover:</strong> MRAP has built-in failover routing. If the nearest regional bucket is unavailable, it automatically routes to the next closest. Use failover controls to shift 100% of routing to a specific bucket during incidents.</li></ul>" },
    { q: "Scenario: A compliance audit requires proving that no S3 object has been tampered with after upload. How do you implement cryptographic integrity verification?", a: "<strong>Detailed Solution:</strong> Use S3 Object Integrity Checksums combined with S3 Object Lock and CloudTrail.<br><ul><li><strong>Checksums:</strong> S3 supports checksum algorithms (CRC32, CRC32C, SHA-1, SHA-256) per object. Specify the checksum during upload. S3 validates the received data matches the checksum and stores it.</li><li><strong>Object Lock (COMPLIANCE):</strong> Lock critical objects in COMPLIANCE mode. Even root cannot delete. Provides proof they haven't been deleted or replaced.</li><li><strong>Audit Trail:</strong> Enable CloudTrail data events for S3. Every access (GET/PUT/DELETE) is logged with requestor identity, time, and object ETag. The ETag is a hash of the object content — changes to content change the ETag, providing tamper evidence.</li></ul>" },
    { q: "Scenario: A malicious insider exports 1 million customer records from S3 to their personal laptop. How do you detect and prevent this in the future?", a: "<strong>Detailed Solution:</strong> Implement DLP controls using GuardDuty, Macie, and preventive IAM conditions.<br><ul><li><strong>Detection (Macie):</strong> Enable Amazon Macie to scan S3 buckets for sensitive data (PII, financial data). Macie generates findings when large volumes of sensitive data are accessed or when access patterns are anomalous.</li><li><strong>Detection (GuardDuty):</strong> GuardDuty detects anomalous S3 API activity. It will flag 'S3 Exfiltration' behavior — e.g., an IAM user downloading thousands of objects in minutes.</li><li><strong>Prevention (IAM Conditions):</strong> Add bucket policy conditions: Deny GetObject if the request does not originate from the corporate VPC Endpoint (<code>aws:sourceVpce</code>).</li></ul>" },
    { q: "Scenario: You have 500 TB of cold data in S3 Standard that hasn't been accessed in 2 years. How do you minimize cost while maintaining reasonable retrieval times?", a: "<strong>Detailed Solution:</strong> Transition to S3 Glacier Instant Retrieval or Deep Archive based on RTO requirements.<br><ul><li><strong>Assessment:</strong> If data needs retrieval within milliseconds (rare but possible), use S3 Glacier Instant Retrieval (~68% cheaper than Standard).</li><li><strong>If minutes/hours acceptable:</strong> Use S3 Glacier Flexible Retrieval (3-5 hours standard) — ~80% cheaper than Standard.</li><li><strong>If rarely/never needed (e.g., regulatory archive):</strong> Use S3 Glacier Deep Archive (12 hours retrieval) — ~95% cheaper than Standard.</li><li><strong>Implementation:</strong> Create S3 Lifecycle Rules transitioning objects to the chosen Glacier tier. Use S3 Intelligent-Tiering Archive Access tier if access patterns are unpredictable.</li></ul>" },
    { q: "Scenario: An S3 bucket is receiving 100,000 GET requests per second for the same 100 hot objects (viral content). Performance degrades. How do you scale?", a: "<strong>Detailed Solution:</strong> Distribute load using CloudFront as a CDN cache layer in front of S3.<br><ul><li><strong>CloudFront Setup:</strong> Place CloudFront in front of the S3 bucket. Configure caching behaviors with appropriate TTLs for the viral content (e.g., 24 hours).</li><li><strong>Cache Hit Ratio:</strong> With 100K req/sec for only 100 objects, CloudFront's cache hit ratio will be nearly 100% after the first cache miss. S3 only receives one request per edge location per TTL period — reducing S3 GET requests by more than 99%.</li><li><strong>S3 Prefix Optimization:</strong> S3 scales to 5,500 GET requests/sec per prefix. If bypassing CloudFront is necessary, distribute objects across multiple key prefixes to parallelize S3's internal request routing.</li></ul>" },
    { q: "Scenario: A team needs to migrate 200 TB from an on-premises NAS to S3, but their internet bandwidth is only 1 Gbps. Calculate if online transfer is feasible and propose alternatives.", a: "<strong>Detailed Solution:</strong> First, calculate the time required for online transfer.<br><ul><li><strong>Calculation:</strong> 200 TB = 200 x 1024 x 8 Gb = 1,638,400 Gb. At 1 Gbps: approximately 19 days. This uses 100% of bandwidth 24/7 — unacceptable for production use.</li><li><strong>Option 1 (AWS DataSync):</strong> If the team can tolerate 19+ days and can spare bandwidth, use AWS DataSync — managed migration agent with encryption, checksum verification, and scheduling to minimize production impact.</li><li><strong>Option 2 (AWS Snowball Edge):</strong> Order 4 x Snowball Edge Storage Optimized (80 TB each). Copy data to the appliances on-premise. Ship to AWS. AWS ingests the data to S3. Total time: ~1 week for the physical process + no bandwidth consumption.</li></ul>" },
    { q: "Scenario: You need to implement a serverless image processing pipeline: user uploads image, auto-resize to 5 thumbnail sizes, store all sizes in S3, send notification.", a: "<strong>Detailed Solution:</strong> Build an event-driven architecture using S3, Lambda, and SNS.<br><ul><li><strong>Architecture:</strong> 1) User uploads to <code>s3://bucket/originals/</code>. 2) S3 Event Notification triggers Lambda. 3) Lambda downloads the original, uses Pillow/Sharp to generate 5 thumbnails. 4) Lambda uploads all 5 to <code>s3://bucket/thumbnails/IMAGEID/SIZE.jpg</code>. 5) Lambda publishes to SNS topic with image metadata. 6) SNS fans out to SQS (for database update) and Email (admin notification).</li><li><strong>Scalability:</strong> Lambda auto-scales — if 10,000 images are uploaded simultaneously, Lambda runs 10,000 concurrent executions, processing them all in parallel.</li></ul>" },
    { q: "Scenario: Design S3 access for a multi-account AWS Organization where each business unit owns their data but a central security team needs read access to all buckets for auditing.", a: "<strong>Detailed Solution:</strong> Use Cross-Account IAM Roles + S3 Bucket Policies with Organization-level conditions.<br><ul><li><strong>Business Unit Buckets:</strong> Each BU bucket has a bucket policy granting access to their own account's IAM roles AND a specific cross-account IAM role ARN from the Security account.</li><li><strong>Security Account Role:</strong> Create an IAM Role in the security account with S3 read permissions. The role trust policy allows the security team's IAM users to assume it. They assume this role to audit any bucket.</li><li><strong>Organization Condition:</strong> Use <code>aws:PrincipalOrgID</code> in bucket policies to ensure only principals from your org can access — prevents accidental cross-org exposure.</li><li><strong>Automation:</strong> Use AWS Config + Lambda to auto-apply the required bucket policy to new S3 buckets created in any account in the org.</li></ul>" }
  ]
};


// ─────────────────────────────────────────────────────────────────────────────
// AWS ▶ IAM
// ─────────────────────────────────────────────────────────────────────────────
window.interviewData["AWS ▶ IAM"] = {
  "Basic": [
    { q: "What is AWS IAM and what does it control?", a: "<strong>Detailed Solution:</strong> AWS Identity and Access Management (IAM) is a global service that controls who (authentication) can do what (authorization) in your AWS account.<br><ul><li><strong>Authentication:</strong> Verifies identity using credentials (username/password for console, Access Keys for CLI/API, temporary session tokens for roles).</li><li><strong>Authorization:</strong> Evaluates policies attached to the identity to determine if the requested action on a resource is allowed or denied.</li><li><strong>Key Principle:</strong> IAM follows the Principle of Least Privilege — grant only the permissions absolutely necessary to perform a specific task.</li></ul>" },
    { q: "What are the main IAM entities: Users, Groups, Roles, and Policies?", a: "<strong>Detailed Solution:</strong> IAM has four core building blocks.<br><ul><li><strong>IAM Users:</strong> Represents a person or application with a permanent identity. Has long-term credentials (password + Access Key).</li><li><strong>IAM Groups:</strong> A collection of IAM users. Policies attached to the group apply to all members. Simplifies permission management (e.g., 'Developers' group).</li><li><strong>IAM Roles:</strong> An identity with temporary credentials. Assumed by trusted entities (EC2, Lambda, another user, cross-account). No permanent credentials stored. The recommended way to grant AWS service access.</li><li><strong>IAM Policies:</strong> JSON documents defining allowed/denied actions. Attached to users, groups, or roles.</li></ul>" },
    { q: "What is the difference between an IAM Role and an IAM User?", a: "<strong>Detailed Solution:</strong> The key difference is credential permanence and who uses them.<br><ul><li><strong>IAM User:</strong> Represents a specific person/app. Has static, long-lived credentials. If compromised, the key works indefinitely until manually rotated or deactivated.</li><li><strong>IAM Role:</strong> Provides TEMPORARY credentials (STS token: Access Key + Secret + Session Token) that automatically expire after 1-12 hours. No stored long-term credentials. Best for AWS services (EC2, Lambda), cross-account access, and federated identities (SSO).</li></ul>" },
    { q: "What is an IAM Policy and how is it structured?", a: "<strong>Detailed Solution:</strong> An IAM Policy is a JSON document that defines permissions.<br><ul><li><strong>Key Elements:</strong> <code>Version</code> (always '2012-10-17'), <code>Statement</code> (array of permission blocks), <code>Effect</code> (Allow/Deny), <code>Action</code> (AWS API calls, e.g., <code>s3:GetObject</code>), <code>Resource</code> (ARN of the resource), <code>Condition</code> (optional — conditional logic).</li><li><strong>Types:</strong> Identity-based (attached to user/role/group), Resource-based (attached to resource like S3 bucket), Permissions Boundaries, SCPs (AWS Organizations), Session Policies.</li></ul>" },
    { q: "What is the IAM Policy Evaluation Logic (allow vs deny)?", a: "<strong>Detailed Solution:</strong> When a request is made, IAM evaluates all applicable policies using this decision tree:<br><ol><li>Explicit DENY anywhere — DENIED (explicit deny always wins).</li><li>If within AWS Organization — Check SCP. If SCP denies — DENIED.</li><li>Check Resource-based policies. If Allow — ALLOWED (cross-account).</li><li>Check IAM Permission Boundaries. If action not in boundary — DENIED.</li><li>Check Identity-based policies. If Allow and no deny found — ALLOWED.</li><li>Default: DENIED (implicit deny — if no explicit allow, deny).</li></ol>" },
    { q: "What is AWS STS (Security Token Service) and how does it work with IAM Roles?", a: "<strong>Detailed Solution:</strong> STS generates short-lived, temporary AWS credentials for assuming IAM Roles.<br><ul><li><strong>Process:</strong> An entity calls <code>sts:AssumeRole</code> API. STS checks the role's Trust Policy to verify the caller is allowed to assume it. If approved, STS issues temporary credentials: Access Key, Secret Key, and Session Token with an expiration.</li><li><strong>Use Cases:</strong> EC2 instances assuming roles (via Instance Profile), Lambda assuming execution roles, cross-account access, SSO federation (SAML/OIDC identity provider).</li></ul>" },
    { q: "What is the difference between an AWS Managed Policy and a Customer Managed Policy?", a: "<strong>Detailed Solution:</strong> Both are IAM policies, but they differ in ownership and flexibility.<br><ul><li><strong>AWS Managed Policies:</strong> Pre-built by AWS. Examples: <code>AmazonS3FullAccess</code>, <code>ReadOnlyAccess</code>. AWS maintains and updates them when new services/features are added. Cannot be modified by the customer.</li><li><strong>Customer Managed Policies:</strong> Created and maintained by you. Allows precise, principle-of-least-privilege control. Can be versioned (keep up to 5 versions). Reusable across multiple identities. Best practice for production environments.</li></ul>" },
    { q: "What is Multi-Factor Authentication (MFA) in IAM and why is it critical?", a: "<strong>Detailed Solution:</strong> MFA adds a second factor of authentication beyond a password.<br><ul><li><strong>How it works:</strong> After entering username/password, the user must provide a time-based one-time password (TOTP) from an MFA device (Google Authenticator, hardware key, SMS).</li><li><strong>Criticality:</strong> If a user's password is compromised (phishing, credential stuffing), MFA prevents unauthorized access since the attacker doesn't have the physical MFA device.</li><li><strong>Best Practice:</strong> Enable MFA on the root account immediately. Enforce MFA for all IAM users with console access using an IAM policy condition: <code>aws:MultiFactorAuthPresent: true</code>.</li></ul>" },
    { q: "What is an IAM Permission Boundary?", a: "<strong>Detailed Solution:</strong> A Permission Boundary is an IAM policy that sets the maximum permissions an IAM entity (user or role) can have.<br><ul><li><strong>Analogy:</strong> Think of it as a fence. Even if a user's identity policy says 'allow s3:*', if the permission boundary only allows 's3:GetObject', the user can only GetObject.</li><li><strong>Use Case:</strong> Allows you to delegate IAM user/role creation to developers without letting them escalate their own privileges. A dev team lead can create roles but can't grant permissions beyond what the boundary allows.</li></ul>" },
    { q: "What is the AWS Root Account and why should it not be used for daily operations?", a: "<strong>Detailed Solution:</strong> The root account is the initial AWS account created with an email address — it has unrestricted access to all services.<br><ul><li><strong>Risks:</strong> Cannot be limited by IAM policies. If compromised, an attacker has complete control over the entire AWS account. Cannot be restricted even by SCPs (it bypasses them within the account).</li><li><strong>Best Practices:</strong> Enable MFA on root immediately. Create an IAM admin user for daily operations. Never generate Access Keys for root. Lock root credentials in a secure vault. Only use root for specific tasks that require it (e.g., closing the AWS account, changing support plan).</li></ul>" }
  ],
  "Moderate Scenario": [
    { q: "Scenario: A developer accidentally left AWS Access Keys in a public GitHub repo. The keys have S3 and EC2 permissions. What do you do immediately?", a: "<strong>Detailed Solution:</strong> Treat this as a critical security incident. Time is everything — automated scanners find and abuse leaked keys in minutes.<br><ul><li><strong>Step 1 (Immediate — less than 60 sec):</strong> Go to IAM → Users → The User → Security Credentials → Deactivate and DELETE the compromised access key immediately.</li><li><strong>Step 2 (Assess Damage):</strong> In AWS CloudTrail, filter events by the compromised Access Key ID to see all API calls made. Look for: S3 GetObject/PutObject, EC2 RunInstances, IAM CreateUser (attacker creating a backdoor).</li><li><strong>Step 3 (Remediate):</strong> Delete any resources the attacker created. Revoke any new credentials created.</li><li><strong>Step 4 (Prevent):</strong> Enable AWS Secrets Manager or git-secrets pre-commit hook to prevent future leaks. Enable GuardDuty for anomalous API detection.</li></ul>" },
    { q: "Scenario: A Lambda function needs to read secrets from AWS Secrets Manager and write results to DynamoDB. What IAM configuration is required?", a: "<strong>Detailed Solution:</strong> Use an IAM Execution Role for Lambda — never hardcode credentials.<br><ul><li><strong>Step 1 (Create Role):</strong> Create an IAM Role. Trust policy: allow <code>lambda.amazonaws.com</code> to assume the role.</li><li><strong>Step 2 (Attach Policies):</strong> Attach a custom policy with minimal permissions: <code>secretsmanager:GetSecretValue</code> on the specific secret ARN. <code>dynamodb:PutItem</code> on the specific DynamoDB table ARN. <code>logs:CreateLogGroup</code>, <code>logs:CreateLogStream</code>, <code>logs:PutLogEvents</code> for CloudWatch Logs.</li><li><strong>Step 3 (Assign):</strong> Assign this role to the Lambda function as its Execution Role. Lambda automatically gets temporary credentials via the Instance Metadata Service.</li></ul>" },
    { q: "Scenario: You want to give a third-party auditing company read-only access to your AWS account without creating long-term IAM users. How?", a: "<strong>Detailed Solution:</strong> Use cross-account IAM Role assumption — the industry standard for third-party access.<br><ul><li><strong>Step 1 (Create Role in Your Account):</strong> Create an IAM Role with <code>ReadOnlyAccess</code> managed policy. Set the Trust Policy to allow the auditor's AWS Account ID to assume it.</li><li><strong>Step 2 (Add ExternalId Condition):</strong> Add a condition requiring an <code>sts:ExternalId</code> (a shared secret UUID) in the trust policy. This prevents confused deputy attacks.</li><li><strong>Step 3 (Auditor Access):</strong> The auditor uses their own IAM user to call <code>sts:AssumeRole</code> with your role ARN and the ExternalId. They receive temporary credentials valid for 1-12 hours.</li></ul>" },
    { q: "Scenario: Developers need to deploy to production S3 and ECS from their local machines. How do you set up secure, auditable access?", a: "<strong>Detailed Solution:</strong> Use IAM Identity Center (SSO) with AWS CLI v2 — no long-term access keys on developer machines.<br><ul><li><strong>Setup:</strong> Configure IAM Identity Center connected to your corporate IdP (Okta, AD). Create Permission Sets in IAM Identity Center mapping to IAM roles in the production account.</li><li><strong>Developer Workflow:</strong> Run <code>aws sso login --profile prod-deployer</code>. Browser opens, developer authenticates via SSO/MFA. CLI receives short-lived temporary credentials automatically. Credentials expire in 1-8 hours. All API calls logged in CloudTrail with the developer's SSO username — full audit trail.</li></ul>" },
    { q: "Scenario: An EC2 instance needs to assume a role in another AWS account (Account B) to write logs to an S3 bucket in Account B. How do you configure this?", a: "<strong>Detailed Solution:</strong> Configure a cross-account role assumption chain.<br><ul><li><strong>Account B Setup:</strong> Create an IAM Role (LogWriterRole) with <code>s3:PutObject</code> permission on the target bucket. Trust Policy: allow Account A's EC2 instance role ARN to assume LogWriterRole.</li><li><strong>Account A Setup:</strong> Ensure the EC2 Instance Profile (IAM Role) has <code>sts:AssumeRole</code> permission targeting the LogWriterRole ARN in Account B.</li><li><strong>Application Code:</strong> The app running on EC2 calls <code>sts.assume_role(RoleArn='arn:aws:iam::ACCOUNT_B_ID:role/LogWriterRole')</code>. Gets temporary credentials. Uses those credentials to write to the S3 bucket in Account B.</li></ul>" },
    { q: "Scenario: A security audit flags that 40% of IAM users in your organization haven't logged in for 90+ days. What actions do you take?", a: "<strong>Detailed Solution:</strong> Use IAM Access Advisor and Credential Report to identify and remediate stale identities.<br><ul><li><strong>Detection:</strong> Generate IAM Credential Report (download CSV with last login, key usage dates for all users). Use IAM Access Advisor per user to see which services they accessed and when.</li><li><strong>Automation:</strong> Use AWS Config rule <code>iam-user-unused-credentials-check</code> to flag users inactive for 90 days. Or write a Lambda function triggered daily to parse the Credential Report and disable keys/users inactive over 90 days.</li><li><strong>Policy:</strong> Implement a joiner/mover/leaver process. Integrate with HR system — when an employee offboards, trigger an automation to disable their IAM user immediately.</li></ul>" },
    { q: "Scenario: You want to prevent any IAM user or role in your AWS account from deleting CloudTrail logs — even the account admin.", a: "<strong>Detailed Solution:</strong> Combine S3 Object Lock and a restrictive IAM policy with an SCP in AWS Organizations.<br><ul><li><strong>S3 Object Lock:</strong> Enable Object Lock (COMPLIANCE mode) on the CloudTrail S3 bucket with a 7-year retention period. No one can delete the log objects.</li><li><strong>SCP (Service Control Policy):</strong> Create an SCP at the Organizations root level: Deny <code>cloudtrail:StopLogging</code>, <code>cloudtrail:DeleteTrail</code>, <code>cloudtrail:UpdateTrail</code> for all principals. Even the account root cannot override an SCP denial for these actions.</li><li><strong>Additional:</strong> Enable CloudTrail log file integrity validation. CloudTrail generates a daily digest file with SHA-256 hashes of all log files. Validate with AWS CLI: <code>aws cloudtrail validate-logs</code>.</li></ul>" },
    { q: "Scenario: Users in the 'Developers' IAM group should only be able to launch EC2 instances of type t3.micro and t3.small. How do you enforce this?", a: "<strong>Detailed Solution:</strong> Use IAM Policy Conditions with the <code>ec2:InstanceType</code> condition key.<br><ul><li><strong>Policy:</strong> Create a customer managed policy for the Developers group: Effect Allow, Action <code>ec2:RunInstances</code>, Resource all instances, Condition StringEquals <code>ec2:InstanceType</code> to ['t3.micro', 't3.small'].</li><li><strong>Additionally:</strong> Deny <code>ec2:ModifyInstanceAttribute</code> to prevent changing the instance type after launch.</li><li><strong>Result:</strong> Attach this policy to the Developers group. Any attempt to launch an m5.large or c5.xlarge will result in an AccessDenied error.</li></ul>" },
    { q: "Scenario: A microservices application runs on EKS (Kubernetes). Each pod (microservice) needs different AWS permissions. How do you securely provide per-pod IAM access?", a: "<strong>Detailed Solution:</strong> Use IRSA (IAM Roles for Service Accounts) — the EKS-native solution.<br><ul><li><strong>How IRSA works:</strong> An OIDC identity provider is created from EKS's OIDC endpoint. IAM roles are created with trust policies that reference the EKS OIDC provider and the specific Kubernetes namespace + service account name. Pods using that service account automatically receive temporary AWS credentials via a projected service account token — no static keys mounted in the pod.</li><li><strong>Result:</strong> payment-service pod assumes PaymentRole (DynamoDB access). user-service pod assumes UserRole (RDS access). Credentials are automatically rotated.</li></ul>" },
    { q: "Scenario: How do you implement break-glass emergency access to your AWS account if your IAM Identity Center/SSO is unavailable?", a: "<strong>Detailed Solution:</strong> Pre-create a break-glass IAM user with a locked-down access pattern.<br><ul><li><strong>Setup:</strong> Create a dedicated break-glass IAM User with <code>AdministratorAccess</code>. Enforce MFA (virtual or hardware token). Store credentials in a sealed, physically-secured vault or a privileged access management (PAM) system.</li><li><strong>Access Control:</strong> Add an IAM condition requiring MFA for all API calls from this user. Restrict console access to this user's session with a very short timeout.</li><li><strong>Alerting:</strong> Set a CloudWatch alarm on CloudTrail events for this specific username. Any use of this account triggers an immediate PagerDuty/SNS notification to the security team — use of break-glass is always an incident.</li></ul>" }
  ],
  "Advanced Scenario": [
    { q: "Scenario: Design a zero-trust IAM architecture for a 500-account AWS Organization where teams are autonomous but security controls are centrally enforced.", a: "<strong>Detailed Solution:</strong> Implement a multi-layered IAM governance model using AWS Organizations + IAM Identity Center + SCPs + Permission Boundaries.<br><ul><li><strong>Layer 1 — SCPs:</strong> Apply preventive guardrails at the org/OU level via SCPs. Deny: leaving the organization, disabling GuardDuty, creating root user keys, using non-approved regions.</li><li><strong>Layer 2 — IAM Identity Center:</strong> Centralized access. All human access goes through SSO with MFA enforced. Permission Sets define role templates. No individual IAM users in member accounts.</li><li><strong>Layer 3 — Permission Boundaries:</strong> Apply to all roles in member accounts. Boundaries set the max permissions — teams can create their own roles but can't grant themselves permissions beyond the boundary.</li><li><strong>Layer 4 — AWS Config:</strong> Continuous compliance monitoring. Auto-remediate non-compliant IAM configurations (MFA disabled, public S3, no encryption).</li></ul>" },
    { q: "Scenario: An attacker gained access to an IAM role with AdministratorAccess. They created a new IAM user and access key as a backdoor before you detected them. Describe the full incident response.", a: "<strong>Detailed Solution:</strong> Execute a structured incident response (NIST/AWS IR framework).<br><ul><li><strong>Contain (less than 5 min):</strong> Attach an explicit DENY all policy to the compromised role immediately. This prevents new API calls. Revoke all active STS sessions for the role using <code>iam:put-role-policy</code> with a deny-all inline policy.</li><li><strong>Identify:</strong> Query CloudTrail for ALL actions taken by the compromised role. Find the backdoor IAM user ARN. Check: new IAM users, new access keys, new roles, changes to trust policies.</li><li><strong>Eradicate:</strong> Delete the backdoor IAM user and all associated access keys. Deactivate and delete any other credentials created during the breach. Audit all IAM policies for malicious changes.</li><li><strong>Recover:</strong> Rotate the original compromised role's credentials. Tighten permissions. Review and apply principle of least privilege.</li></ul>" },
    { q: "Scenario: Implement Attribute-Based Access Control (ABAC) in IAM where a developer can only access AWS resources tagged with their team name.", a: "<strong>Detailed Solution:</strong> Use IAM tag conditions combined with principal tag propagation.<br><ul><li><strong>Tag IAM Principals:</strong> Tag each IAM user/role with their team: <code>Team = Backend</code>, <code>Team = Frontend</code>.</li><li><strong>Tag Resources:</strong> Tag EC2 instances, S3 buckets, RDS clusters with the same <code>Team</code> tag.</li><li><strong>ABAC Policy:</strong> Create one universal policy: Effect Allow, Action ec2:*, Resource *, Condition StringEquals ec2:ResourceTag/Team to '${aws:PrincipalTag/Team}'.</li><li><strong>Result:</strong> Backend developer automatically gets access to all resources tagged <code>Team=Backend</code>. No manual policy updates needed when team membership changes — just update the principal's tag.</li></ul>" },
    { q: "Scenario: A security team wants to prevent privilege escalation — where an IAM user with limited permissions grants themselves or another entity full admin access. How?", a: "<strong>Detailed Solution:</strong> Privilege escalation via IAM is a critical attack vector. Multiple controls are needed.<br><ul><li><strong>Control 1: Deny IAM write actions unless using Permission Boundary.</strong> Create an SCP or IAM policy that denies <code>iam:CreateRole</code>, <code>iam:AttachRolePolicy</code>, etc., UNLESS the caller includes a specific Permission Boundary ARN that limits what the new role can do.</li><li><strong>Control 2: Deny <code>iam:PassRole</code> broadly.</strong> Restrict PassRole to only specific ARNs. This prevents a user from passing an admin role to a Lambda function they control.</li><li><strong>Control 3: IAM Access Analyzer.</strong> Enable IAM Access Analyzer to identify external access paths and policy findings that enable privilege escalation.</li></ul>" },
    { q: "Scenario: A financial services firm requires that no AWS API call can be made without a hardware MFA token (not TOTP soft tokens). How do you enforce this globally?", a: "<strong>Detailed Solution:</strong> Use IAM conditions combined with SCPs to enforce MFA presence globally.<br><ul><li><strong>SCP at Org Root:</strong> Create an SCP denying all actions unless <code>aws:MultiFactorAuthPresent = true</code> AND <code>aws:MultiFactorAuthAge</code> less than 300 (MFA used within last 5 minutes). Apply to all OUs.</li><li><strong>Hardware-Specific Enforcement:</strong> IAM cannot natively distinguish hardware vs. soft TOTP tokens via conditions. To enforce hardware tokens: use AWS IAM Identity Center with hardware FIDO2/WebAuthn keys as MFA method. Configure the IdP to only accept hardware authenticators.</li><li><strong>Exception:</strong> Service roles (Lambda, EC2) do not use MFA — exclude them from the SCP condition using an SCP exception for <code>aws:PrincipalIsAWSService = true</code>.</li></ul>" },
    { q: "Scenario: Your company uses Terraform to manage IAM policies as code. A PR is merged with an overly permissive policy ('Action: *', 'Resource: *'). How do you prevent this?", a: "<strong>Detailed Solution:</strong> Implement infrastructure-as-code (IaC) security scanning in the CI/CD pipeline.<br><ul><li><strong>Pre-commit:</strong> Install <code>git-secrets</code> and <code>tfsec</code> as pre-commit hooks to scan Terraform files for wildcard IAM policies before the developer even pushes.</li><li><strong>CI Pipeline:</strong> Add <code>tfsec</code>, <code>Checkov</code>, or <code>Regula</code> to the CI pipeline. If the scan detects <code>Action: '*'</code> or <code>Resource: '*'</code> in an IAM policy, fail the pipeline — the PR cannot be merged.</li><li><strong>AWS Runtime:</strong> Use AWS Config rule <code>iam-policy-no-statements-with-admin-access</code> to continuously scan all IAM policies in the account and alert/auto-remediate if any policy with admin-level wildcard access is found.</li></ul>" },
    { q: "Scenario: Design an IAM architecture for a SaaS platform where each customer's data in the same AWS account must be isolated — one customer cannot access another's data.", a: "<strong>Detailed Solution:</strong> Use IAM dynamic session policies combined with resource tagging for tenant isolation.<br><ul><li><strong>Architecture:</strong> All customer data in DynamoDB is tagged <code>TenantID = CUSTOMER_ID</code>. S3 objects stored under prefix <code>/customers/CUSTOMER_ID/</code>.</li><li><strong>Token Vending Machine:</strong> When a customer logs in, your auth service calls <code>sts:AssumeRole</code> for a 'TenantRole' with a dynamic session policy scoped to that customer's resources only. Example: <code>arn:aws:s3:::bucket/customers/CUSTOMER_123/*</code>.</li><li><strong>Enforcement:</strong> The customer's frontend receives temporary credentials with only their scoped session policy. Even if they reverse-engineer the API, they cannot access another customer's data as their credentials lack permission for that prefix.</li></ul>" },
    { q: "Scenario: How do you achieve federated access to the AWS Console for 10,000 employees using your existing corporate Active Directory, without creating IAM users for each employee?", a: "<strong>Detailed Solution:</strong> Use AWS IAM Identity Center (formerly SSO) federated with Active Directory.<br><ul><li><strong>Setup:</strong> Connect IAM Identity Center to AWS Managed Microsoft AD (or existing on-prem AD via AD Connector). IAM Identity Center automatically syncs users and groups from AD.</li><li><strong>Permission Sets:</strong> Create IAM Permission Sets (read-only, developer, admin) mapping to IAM roles in target accounts. Assign AD groups to Permission Sets.</li><li><strong>Employee Experience:</strong> Employee goes to IAM Identity Center portal URL. Signs in with their corporate AD credentials + MFA. Sees a list of AWS accounts and roles they have access to. Clicks to access the console — receives temporary credentials. No IAM users created, no passwords to manage.</li></ul>" },
    { q: "Scenario: An automated CI/CD pipeline needs to deploy to 20 different AWS accounts. How do you manage IAM access for the pipeline securely?", a: "<strong>Detailed Solution:</strong> Use a hub-and-spoke role assumption model from a central CI/CD account.<br><ul><li><strong>Architecture:</strong> The CI/CD tool (Jenkins/GitHub Actions) runs in a central 'CICD Account'. It has one IAM Role (PipelineRole) with <code>sts:AssumeRole</code> permission targeting deployment roles in all 20 accounts.</li><li><strong>Deployment Roles (in each account):</strong> Each account has a 'DeploymentRole' with only the permissions needed for that account's deployments. Trust policy allows only the PipelineRole ARN from the CICD account to assume it.</li><li><strong>Security:</strong> Short-lived STS tokens. GitHub Actions uses OIDC to authenticate to AWS without any stored access keys via <code>aws-actions/configure-aws-credentials</code>.</li></ul>" },
    { q: "Scenario: How do you detect and remediate IAM misconfigurations at scale across a 200-account AWS Organization in real time?", a: "<strong>Detailed Solution:</strong> Build a real-time IAM governance pipeline using EventBridge, Config, and Security Hub.<br><ul><li><strong>AWS Config (Continuous Compliance):</strong> Deploy Config conformance packs across all accounts via AWS Organizations. Key rules: <code>iam-root-access-key-check</code>, <code>iam-user-mfa-enabled</code>, <code>iam-no-inline-policy-check</code>, <code>access-keys-rotated</code>. Non-compliant resources appear in the Security Hub aggregator account within minutes.</li><li><strong>EventBridge (Real-time):</strong> Create EventBridge rules across accounts forwarding <code>CreateAccessKey</code>, <code>CreateUser</code>, <code>AttachUserPolicy</code> CloudTrail events to a central SNS topic. A Lambda evaluates the event for risk.</li><li><strong>Auto-Remediation:</strong> AWS Config auto-remediation Lambda: if MFA disabled — disable password, send ticket to IT helpdesk. If inline policy added — delete it, notify the team.</li></ul>" }
  ]
};


// ─────────────────────────────────────────────────────────────────────────────
// AWS ▶ ASG (Auto Scaling Groups)
// ─────────────────────────────────────────────────────────────────────────────
window.interviewData["AWS ▶ ASG"] = {
  "Basic": [
    { q: "What is an Auto Scaling Group (ASG) in AWS?", a: "<strong>Detailed Solution:</strong> An Auto Scaling Group (ASG) is a collection of EC2 instances managed as a logical unit for automatic scaling and self-healing.<br><ul><li><strong>Core Function:</strong> Automatically adds instances (scale out) when demand increases and removes instances (scale in) when demand decreases — maintaining optimal performance at minimal cost.</li><li><strong>Self-healing:</strong> If an instance fails health checks, the ASG automatically terminates it and launches a replacement, maintaining the desired capacity.</li><li><strong>Key Settings:</strong> Minimum capacity, Maximum capacity, and Desired capacity — the ASG always tries to maintain the desired number of healthy instances within the min/max bounds.</li></ul>" },
    { q: "What is a Launch Template and how does it differ from a Launch Configuration?", a: "<strong>Detailed Solution:</strong> Both define the configuration for instances launched by an ASG, but Launch Templates are the modern replacement.<br><ul><li><strong>Launch Template (Recommended):</strong> Supports versioning. Can define multiple instance types (mix of On-Demand + Spot). Supports T2/T3 unlimited mode. Can be used with EC2 Fleet. Supports all current EC2 features.</li><li><strong>Launch Configuration (Legacy):</strong> Cannot be modified after creation (must delete and create new). No versioning. Only supports a single instance type. AWS recommends migrating to Launch Templates.</li></ul>" },
    { q: "What are the different ASG scaling policies?", a: "<strong>Detailed Solution:</strong> ASG supports multiple scaling strategies for different use cases.<br><ul><li><strong>Simple Scaling:</strong> Scale by a fixed amount when a CloudWatch alarm triggers. Cooldown period prevents rapid successive scaling.</li><li><strong>Step Scaling:</strong> Scale by different amounts based on alarm severity (e.g., CPU 60-70% — add 1, CPU 70-90% — add 3, CPU greater than 90% — add 5).</li><li><strong>Target Tracking:</strong> Automatically add/remove instances to maintain a target metric value (e.g., keep average CPU at 50%). AWS manages the alarm thresholds automatically.</li><li><strong>Predictive Scaling:</strong> Uses ML to forecast future traffic and proactively scales ahead of predicted load.</li><li><strong>Scheduled Scaling:</strong> Scale at specific times (e.g., increase capacity at 9 AM on weekdays).</li></ul>" },
    { q: "What is a Cooldown Period in an ASG and why is it important?", a: "<strong>Detailed Solution:</strong> The cooldown period is a configurable time (default 300 seconds) during which the ASG suspends scaling activities after a scaling event.<br><ul><li><strong>Purpose:</strong> Prevents rapid, consecutive scaling actions that could cause resource thrashing. After launching a new instance, the cooldown gives the new instance time to boot, register with the LB, and handle traffic before metrics are re-evaluated.</li><li><strong>Optimization:</strong> If you're using golden AMIs (fast boot) and target tracking, reduce the cooldown to 60-90 seconds for faster response.</li></ul>" },
    { q: "What are the types of health checks an ASG can use?", a: "<strong>Detailed Solution:</strong> ASG supports two health check types.<br><ul><li><strong>EC2 Health Check (Default):</strong> Checks the hardware/hypervisor layer. Marks an instance unhealthy if it's in any state other than 'running' (stopped, terminated, impaired). Does NOT check if the application is working.</li><li><strong>ELB Health Check:</strong> The ASG asks the Load Balancer if the instance is healthy. If the app is returning 500 errors (but the EC2 hardware is fine), the ASG will detect it and replace the instance. Always enable ELB health checks when using a load balancer.</li></ul>" },
    { q: "What is the difference between Scale Out and Scale Up in the context of ASG?", a: "<strong>Detailed Solution:</strong> These are two fundamental scaling strategies.<br><ul><li><strong>Scale Out (Horizontal Scaling — ASG's approach):</strong> Add more instances of the same type. ASG launches additional EC2 instances to distribute load. The application must be stateless or share state externally (ElastiCache, RDS).</li><li><strong>Scale Up (Vertical Scaling):</strong> Move to a bigger instance type (e.g., t3.micro to m5.large). EC2 must be stopped and restarted with a different instance type. ASG cannot automatically scale vertically — you must update the launch template and perform an instance refresh.</li></ul>" },
    { q: "What is a Termination Policy in an ASG?", a: "<strong>Detailed Solution:</strong> The termination policy determines which instance an ASG chooses to terminate during a scale-in event.<br><ul><li><strong>Default Policy (in order):</strong> 1) Select the AZ with the most instances. 2) From that AZ, find instances using the oldest launch template/configuration. 3) If tie, terminate the one closest to the next billing hour (saves cost).</li><li><strong>Other Policies:</strong> OldestInstance, NewestInstance, OldestLaunchConfiguration, ClosestToNextInstanceHour, AllocationStrategy (for mixed instance/Spot fleets).</li></ul>" },
    { q: "What is a Warm Pool in an ASG and when should you use it?", a: "<strong>Detailed Solution:</strong> A Warm Pool is a pre-initialized pool of stopped or running EC2 instances ready to join the ASG instantly during scale-out events.<br><ul><li><strong>Problem it solves:</strong> If your user-data scripts take 10+ minutes (installing dependencies, running migrations), scale-out is slow. During a sudden traffic spike, instances aren't ready in time.</li><li><strong>How it works:</strong> AWS pre-launches instances and runs the user-data. Then puts them in 'Stopped' state in the Warm Pool. On scale-out, AWS simply starts these pre-configured instances — takes seconds instead of minutes.</li></ul>" },
    { q: "What is the Instance Refresh feature in an ASG?", a: "<strong>Detailed Solution:</strong> Instance Refresh is an ASG feature that replaces all instances in the group rolling with a new launch template version (e.g., after an AMI update).<br><ul><li><strong>How it works:</strong> You initiate an Instance Refresh. ASG terminates and replaces instances in batches. Configurable 'minimum healthy percentage' (e.g., 80%) ensures at least 80% of instances remain in service at all times during the refresh.</li><li><strong>Use Case:</strong> After baking a new Golden AMI with a patched OS or updated application, trigger an Instance Refresh instead of manually terminating instances one by one.</li></ul>" },
    { q: "How does an ASG interact with multiple Availability Zones?", a: "<strong>Detailed Solution:</strong> Multi-AZ configuration is crucial for ASG fault tolerance.<br><ul><li><strong>Configuration:</strong> You specify multiple subnets from different AZs in the ASG configuration. AWS then distributes instances across these AZs as evenly as possible (AZ Rebalancing).</li><li><strong>AZ Rebalancing:</strong> If an AZ fails and instances are terminated, when it recovers, ASG automatically rebalances by launching new instances in the recovered AZ and possibly terminating excess in other AZs.</li><li><strong>Best Practice:</strong> Always configure ASGs in 2+ AZs. If one AZ's underlying hardware fails, the remaining AZs continue serving traffic with automatic replacement of lost capacity.</li></ul>" }
  ],
  "Moderate Scenario": [
    { q: "Scenario: During a traffic spike, the ASG is scaling out, but new instances take 15 minutes to be ready. Users experience degraded performance. How do you fix this?", a: "<strong>Detailed Solution:</strong> Address the root cause: slow instance initialization.<br><ul><li><strong>Solution 1 (Golden AMI):</strong> Pre-bake all software, dependencies, and application code into a custom AMI. On launch, the instance boots directly into a ready state in 2-3 minutes instead of 15.</li><li><strong>Solution 2 (Warm Pools):</strong> Configure an ASG Warm Pool with pre-initialized stopped instances. Scale-out uses these pre-warmed instances (less than 30 seconds to start) instead of launching fresh ones.</li><li><strong>Solution 3 (Predictive Scaling):</strong> Enable Predictive Scaling if traffic patterns are recurring. ASG proactively adds instances 5-10 minutes before predicted peak, so they're ready when traffic arrives.</li></ul>" },
    { q: "Scenario: Your ASG is scaling out aggressively even though actual application load is not high. CloudWatch shows CPU alarms firing. What could be the issue?", a: "<strong>Detailed Solution:</strong> Investigate the scaling trigger — not all CPU is application load.<br><ul><li><strong>Cause 1 (Noisy Instance):</strong> One instance is running a rogue process (cron job, memory leak causing CPU thrashing). The average CPU metric is elevated by this outlier. Fix: identify the rogue process with CloudWatch agent per-process metrics and kill it.</li><li><strong>Cause 2 (Alarm Configuration):</strong> The CloudWatch alarm is set on maximum CPU, not average. One instance at 100% triggers scale-out even if others are idle. Change to Average across instances.</li><li><strong>Cause 3 (Evaluation Period Too Short):</strong> Alarm triggers after 1 data point. A momentary CPU spike (e.g., GC pause) triggers scale-out. Increase the evaluation period to 3-5 data points to smooth out transient spikes.</li></ul>" },
    { q: "Scenario: You need to deploy a new AMI to the ASG without any downtime, ensuring at least 75% of instances remain healthy at all times.", a: "<strong>Detailed Solution:</strong> Use ASG Instance Refresh with a minimum healthy percentage.<br><ul><li><strong>Step 1:</strong> Update the Launch Template to point to the new AMI version. Create a new version of the Launch Template.</li><li><strong>Step 2:</strong> Update the ASG to use the new Launch Template version.</li><li><strong>Step 3:</strong> Initiate Instance Refresh: set Minimum Healthy Percentage to 75%. ASG will terminate and replace 25% of instances at a time.</li><li><strong>Step 4:</strong> Monitor the refresh progress. The ALB health checks ensure only healthy instances (running new AMI) receive traffic. If replacement instances fail health checks, the refresh pauses automatically.</li></ul>" },
    { q: "Scenario: You want to use a mix of On-Demand and Spot Instances in the ASG to reduce costs while maintaining reliability. How do you configure this?", a: "<strong>Detailed Solution:</strong> Use a Mixed Instances Policy in the Launch Template.<br><ul><li><strong>Configuration:</strong> In the ASG Mixed Instances Policy, set: Base On-Demand capacity: 2 (always 2 On-Demand for reliability). On-Demand Percentage above base: 20% (20% of additional capacity is On-Demand). Spot: 80% of scale-out capacity.</li><li><strong>Multiple Spot Types:</strong> Specify multiple Spot instance pools (m5.large, m5.xlarge, m4.large) for Spot diversity — if one Spot pool is interrupted, the ASG uses another.</li><li><strong>Cost Savings:</strong> Spot instances are up to 90% cheaper than On-Demand. With proper diversification, interruptions are infrequent and handled gracefully via the 2-minute termination notice.</li></ul>" },
    { q: "Scenario: Your ASG is behind an ALB. During deployment, the ALB sends traffic to new instances before they are fully initialized, causing 500 errors. How do you fix this?", a: "<strong>Detailed Solution:</strong> This is a health check timing issue — new instances are marked 'healthy' before the app is fully ready.<br><ul><li><strong>Fix 1 (ASG Health Check Grace Period):</strong> Set an ASG health check grace period that matches your app initialization time. This delays health check evaluation on new instances, giving them time to boot fully.</li><li><strong>Fix 2 (ALB Health Check):</strong> Tighten the ALB health check to use a meaningful endpoint (e.g., <code>/ready</code> that returns 200 only when the app is fully initialized, database connections are established, and caches are warm).</li><li><strong>Fix 3 (Lifecycle Hooks):</strong> Add an <code>autoscaling:EC2_INSTANCE_LAUNCHING</code> lifecycle hook. When a new instance enters the 'Pending:Wait' state, your app signals 'CONTINUE' only after a successful self-health check, preventing premature ALB registration.</li></ul>" },
    { q: "Scenario: ASG is terminating healthy instances during business hours unexpectedly. How do you investigate and prevent this?", a: "<strong>Detailed Solution:</strong> Diagnose by checking ASG activity history and scale-in triggers.<br><ul><li><strong>Step 1 (Activity History):</strong> Check ASG Activity History in the console or via CLI: <code>aws autoscaling describe-scaling-activities</code>. The termination reason is logged here.</li><li><strong>Step 2 (Common Causes):</strong> Scale-in policy is too aggressive (low CPU threshold). Another automation (AWS Operations, Instance Scheduler) is stopping instances. AZ rebalancing is terminating instances in an over-populated AZ.</li><li><strong>Solution (Scale-in Protection):</strong> Enable 'Instance Scale-in Protection' on specific instances you want to protect. Or use a scheduled scaling action to increase minimum capacity during business hours.</li></ul>" },
    { q: "Scenario: You need the ASG to run a custom script (e.g., deregister from a service registry) before terminating an instance. How do you implement this?", a: "<strong>Detailed Solution:</strong> Use ASG Lifecycle Hooks for graceful termination.<br><ul><li><strong>Lifecycle Hook:</strong> Create a lifecycle hook for the <code>autoscaling:EC2_INSTANCE_TERMINATING</code> transition. This puts the instance into 'Terminating:Wait' state, pausing termination.</li><li><strong>Trigger:</strong> The lifecycle hook publishes an event to SNS or EventBridge. A Lambda function receives the event, identifies the instance, SSM's into it, runs the custom deregistration script, drains connections, and completes cleanup.</li><li><strong>Complete:</strong> Lambda calls <code>complete-lifecycle-action</code> with CONTINUE. The ASG then proceeds to terminate the instance. The maximum wait time is 1 hour (heartbeat can be extended).</li></ul>" },
    { q: "Scenario: You have a scheduled job that runs on one specific EC2 instance every night. The ASG keeps terminating that instance. How do you handle this?", a: "<strong>Detailed Solution:</strong> Protect specific instances from scale-in termination.<br><ul><li><strong>Option 1 (Scale-in Protection):</strong> Enable instance-level scale-in protection on the specific instance running the cron job. The ASG won't terminate a protected instance during scale-in. Use automation to enable protection before the cron starts and remove it after.</li><li><strong>Option 2 (Better Architecture):</strong> Migrate the scheduled job from a cron on an EC2 instance to an EventBridge Scheduled Rule triggering a Lambda function. Now the job runs serverlessly — no dependency on a specific EC2 instance surviving ASG scale-in events.</li></ul>" },
    { q: "Scenario: You need to implement a blue/green deployment for an ASG-backed application. Traffic should shift gradually from old to new instances.", a: "<strong>Detailed Solution:</strong> Use two separate ASGs (Blue and Green) and an ALB with weighted target groups.<br><ul><li><strong>Step 1:</strong> Create a new 'Green' ASG with the new Launch Template (new AMI). Register it with a new ALB Target Group (TG-Green).</li><li><strong>Step 2:</strong> The ALB has two target groups: TG-Blue (existing, weight 100) and TG-Green (new, weight 0).</li><li><strong>Step 3:</strong> Gradually shift traffic: Blue 90 / Green 10, then monitor errors. Blue 50 / Green 50, then monitor. Blue 0 / Green 100 for final cutover.</li><li><strong>Step 4:</strong> If Green shows issues, set Green weight back to 0 instantly — the old Blue ASG is still warm and running. Zero-downtime rollback.</li></ul>" },
    { q: "Scenario: Application latency spikes every day at 9 AM when business starts, even though the ASG has time-based scaling configured. What's wrong?", a: "<strong>Detailed Solution:</strong> The scheduled scaling action is triggered too late or instances take too long to join the LB.<br><ul><li><strong>Root Cause:</strong> Scheduled scale-out fires at 9:00 AM. New instances take 3-5 minutes to boot, pass health checks, and become LB-registered. The 9:00-9:05 AM window has insufficient capacity.</li><li><strong>Fix 1 (Earlier Schedule):</strong> Change the scheduled scaling action to fire at 8:45 AM — 15 minutes before business hours. Instances are ready and healthy before load arrives.</li><li><strong>Fix 2 (Warm Pool):</strong> Configure a Warm Pool. Instances are pre-initialized in stopped state. Scale-out uses them (30 seconds to start) instead of fresh boots.</li><li><strong>Fix 3 (Predictive Scaling):</strong> Enable Predictive Scaling — it learns the 9 AM daily pattern and proactively adds instances 10 minutes beforehand.</li></ul>" }
  ],
  "Advanced Scenario": [
    { q: "Scenario: Design a fault-tolerant, cost-optimized ASG architecture for a stateless web application expecting 100 req/sec normally and 10,000 req/sec during sales events.", a: "<strong>Detailed Solution:</strong> Multi-layer scaling with Spot + Predictive + On-Demand baseline.<br><ul><li><strong>Baseline (On-Demand):</strong> Minimum 4 On-Demand instances (2 per AZ) for guaranteed capacity. These never scale in below 4 — protects against full Spot interruption scenarios.</li><li><strong>Scale-Out Pool (Mixed Spot/OD):</strong> Additional capacity is 80% Spot, 20% On-Demand across 6 instance types (m5.large, m5a.large, m4.large, r5.large, c5.large, c5a.large). Spot diversification minimizes interruption impact.</li><li><strong>Scaling Policy:</strong> Target Tracking on ALB RequestCountPerTarget = 100 req/sec/instance. ASG adds instances to keep each instance at 100 req/sec.</li><li><strong>Sales Event:</strong> Enable Predictive Scaling + Scheduled Scaling. Pre-warm to 50 instances 30 minutes before sale. ASG Warm Pool keeps 20 instances pre-initialized to handle burst.</li></ul>" },
    { q: "Scenario: Spot Instance interruptions are causing service degradation for your ASG. How do you architect for Spot resilience?", a: "<strong>Detailed Solution:</strong> Handle Spot interruptions gracefully with multiple layers of protection.<br><ul><li><strong>Interruption Notice Handler:</strong> AWS sends a 2-minute interruption notice to the instance's metadata service. Run a daemon on each instance that polls this endpoint every 5 seconds. When detected, deregister from the LB, drain connections, flush caches to ElastiCache.</li><li><strong>Spot Diversification:</strong> Use 6+ instance families in the Launch Template's Spot allocation. If m5.large Spot pool is interrupted, ASG immediately launches m4.large or m5a.large instances.</li><li><strong>On-Demand Buffer:</strong> Maintain 2-4 On-Demand instances as a floor — these always serve requests during Spot interruption storms.</li><li><strong>Capacity-Optimized Strategy:</strong> Use the Capacity-Optimized Spot allocation strategy — AWS picks the Spot pool with the most available capacity, reducing interruption probability.</li></ul>" },
    { q: "Scenario: Implement a self-healing ASG where if an application-level failure is detected (e.g., JVM crash), the instance is automatically replaced and the on-call team is notified.", a: "<strong>Detailed Solution:</strong> Combine ELB health checks, CloudWatch agent, and EventBridge for full-stack self-healing.<br><ul><li><strong>Health Check:</strong> Configure the ALB health check to a meaningful endpoint (<code>/actuator/health</code>). If JVM crashes, the endpoint fails. ALB marks the instance unhealthy and stops sending traffic. ASG (with ELB health check type enabled) terminates the unhealthy instance and launches a replacement.</li><li><strong>Custom Metric:</strong> Deploy CloudWatch Agent on instances. Emit a custom metric for JVM heap usage, GC pause times. Create a CloudWatch alarm on these metrics.</li><li><strong>Notification:</strong> Create an EventBridge rule matching ASG termination events for health check failures. Route to SNS topic for on-call notification with instance ID and reason.</li></ul>" },
    { q: "Scenario: You need to run database migrations (schema changes) as part of ASG deployments without causing downtime or running migrations on every new instance.", a: "<strong>Detailed Solution:</strong> Separate migration execution from application deployment using a dedicated migration strategy.<br><ul><li><strong>Principle:</strong> Migrations run ONCE, not on every instance. Separating DB migration from ASG instance launch is critical.</li><li><strong>Pattern:</strong> Step 1: Deploy a 'migration runner' instance (not in the ASG) that applies database migrations. This instance is a standalone EC2 launched via a separate CloudFormation/Terraform step. Step 2: After migration succeeds, trigger the ASG Instance Refresh to replace app instances with the new AMI.</li><li><strong>Lifecycle Hook Alternative:</strong> Use an ASG launching lifecycle hook. Only the FIRST instance launched runs migrations (detected via a distributed lock in DynamoDB). Subsequent instances skip migrations and wait for the first to complete.</li></ul>" },
    { q: "Scenario: Your application is stateful (maintains WebSocket connections). ASG scale-in terminates instances with active connections, causing drops. How do you handle this?", a: "<strong>Detailed Solution:</strong> Use graceful connection draining via lifecycle hooks and sticky sessions.<br><ul><li><strong>ALB Connection Draining:</strong> Set the ALB Target Group deregistration delay to the maximum expected WebSocket session duration (e.g., 3600 seconds for 1-hour sessions). When an instance is marked for scale-in, the ALB stops routing NEW connections to it but maintains existing WebSocket connections until they close naturally or the timeout expires.</li><li><strong>Lifecycle Hook:</strong> Create a Terminating:Wait lifecycle hook. A Lambda monitors the instance's active connection count via a CloudWatch custom metric the app emits. When connections reach 0, Lambda calls CONTINUE on the lifecycle. The instance is terminated only after all WebSocket connections have naturally closed.</li></ul>" },
    { q: "Scenario: A multi-region active-passive ASG architecture requires that DR region ASG is always ready to receive 100% traffic within 5 minutes. How do you design this?", a: "<strong>Detailed Solution:</strong> Use ASG Warm Pools in the DR region for near-instant failover.<br><ul><li><strong>DR Region ASG:</strong> Configure ASG with Minimum=0, Desired=0, Maximum=100 in the DR region. Enable a Warm Pool of 50 pre-initialized stopped instances.</li><li><strong>AMI Sync:</strong> Use AWS CodePipeline to build the same AMI in both regions simultaneously. DR warm pool uses the same AMI as production.</li><li><strong>Failover Trigger:</strong> Route53 health check monitors the primary region ALB. On failure, Route53 automatically redirects DNS to the DR region ALB. A Lambda function calls ASG SetDesiredCapacity to 50. Warm pool instances start in 30 seconds. DR is fully operational in less than 2 minutes.</li></ul>" },
    { q: "Scenario: You are running 200 ASGs across 30 AWS accounts. How do you centralize scaling policy management and ensure consistency?", a: "<strong>Detailed Solution:</strong> Use AWS Organizations + CloudFormation StackSets + central Operations account.<br><ul><li><strong>CloudFormation StackSets:</strong> Define ASG scaling policies in a CloudFormation template. Deploy via StackSets across all 30 accounts and all target regions simultaneously from the management account. Any policy change is propagated to all 200 ASGs automatically.</li><li><strong>Tags-Based Governance:</strong> Tag ASGs with <code>ScalingProfile = standard | high-performance | batch</code>. An EventBridge + Lambda automation reads the tag on ASG creation and applies the corresponding scaling policy template from a central S3 bucket.</li><li><strong>Drift Detection:</strong> AWS Config across all accounts detects ASG configuration drift from the CloudFormation template. Auto-remediation Lambda can reapply the correct scaling policies.</li></ul>" },
    { q: "Scenario: Implement a custom scaling metric for an ASG based on the depth of an SQS queue — scale out when queue depth exceeds 1000 messages per instance.", a: "<strong>Detailed Solution:</strong> Publish a custom CloudWatch metric representing queue depth per ASG instance and use Target Tracking scaling.<br><ul><li><strong>Custom Metric:</strong> Deploy a Lambda (triggered every 1 minute by EventBridge) that: 1) Calls SQS GetQueueAttributes to get ApproximateNumberOfMessages (e.g., 5000). 2) Calls ASG DescribeAutoScalingGroups to get InService instance count (e.g., 4). 3) Calculates the ratio: 5000/4 = 1250 messages/instance. 4) Publishes this as a CloudWatch custom metric.</li><li><strong>Target Tracking Policy:</strong> Create a Target Tracking scaling policy on the ASG targeting the custom metric at a value of 1000. ASG automatically adds instances when queue depth per instance exceeds 1000 and removes them when it drops below.</li></ul>" },
    { q: "Scenario: During an incident, you need to immediately add 50 instances to an ASG that currently has 10, while bypassing all cooldown periods.", a: "<strong>Detailed Solution:</strong> Use the SetDesiredCapacity API with HonorCooldown=false for immediate emergency scaling.<br><ul><li><strong>CLI Command:</strong> <code>aws autoscaling set-desired-capacity --auto-scaling-group-name MyASG --desired-capacity 60 --no-honor-cooldown</code>. This immediately signals the ASG to launch 50 new instances without waiting for any cooldown period.</li><li><strong>Runbook Automation:</strong> Pre-create an SSM Automation Runbook that executes this command. During an incident, on-call engineers can trigger the runbook with one click from the SSM console, reducing incident response time.</li><li><strong>Consideration:</strong> Ensure the ASG Maximum is set to at least 60. If maximum is 10, the desired capacity cannot exceed it. Pre-configure the maximum to handle emergency capacity.</li></ul>" },
    { q: "Scenario: Design an ASG-based architecture for a machine learning inference service that runs GPU-intensive workloads with highly variable traffic and tight cost constraints.", a: "<strong>Detailed Solution:</strong> Optimize for GPU Spot Instances with SQS-driven scaling.<br><ul><li><strong>Instance Type:</strong> Use Spot p3.2xlarge or g4dn.xlarge GPU instances. Add g5.xlarge as fallback. GPU Spot savings can be 70-90% vs On-Demand.</li><li><strong>Architecture:</strong> Instead of HTTP load balancing, use SQS-based async inference. Requests go to an SQS queue. ASG instances poll the queue, run GPU inference, write results to S3/DynamoDB, and send a callback.</li><li><strong>Custom Scaling:</strong> Scale based on SQS depth per instance. Set scale-in cooldown to 10 minutes (GPU instances are expensive to boot).</li><li><strong>Spot Handling:</strong> On Spot interruption, the instance checkpoints its current work state to S3. The SQS message is returned to the queue (visibility timeout). Another instance picks it up and resumes from the checkpoint — no work is lost.</li></ul>" }
  ]
};

