window.interviewData["AWS ▶ Elastic Beanstalk"] = {
  "Basic": [
    { q: "What is AWS Elastic Beanstalk?", a: "<strong>Detailed Solution:</strong> Elastic Beanstalk is a PaaS (Platform as a Service) offering from AWS.<br><ul><li><strong>Purpose:</strong> It allows developers to deploy and manage applications in the AWS Cloud without worrying about the infrastructure that runs those applications.</li><li><strong>How it works:</strong> You simply upload your code, and Elastic Beanstalk automatically handles the deployment, from capacity provisioning, load balancing, auto-scaling to application health monitoring.</li></ul>" },
    { q: "What languages and platforms are supported by Elastic Beanstalk?", a: "<strong>Detailed Solution:</strong> Elastic Beanstalk supports multiple platforms natively.<br><ul><li><strong>Supported:</strong> Java, .NET, PHP, Node.js, Python, Ruby, Go, and Docker on familiar servers such as Apache, Nginx, Passenger, and IIS.</li><li><strong>Custom:</strong> If your language/framework isn't supported, you can use a custom Docker container.</li></ul>" }
  ],
  "Moderate Scenario": [
    { q: "Scenario: You need to deploy a new version of an Elastic Beanstalk application with zero downtime. Which deployment policy should you choose?", a: "<strong>Detailed Solution:</strong> Use Immutable or Rolling with additional batch deployments.<br><ul><li><strong>Immutable:</strong> Creates a fresh Auto Scaling Group with the new version, tests it, and then swaps it with the old ASG. Ensures zero downtime and easy rollback.</li><li><strong>Rolling with additional batch:</strong> Launches an extra batch of instances with the new version, before taking old instances out of service, ensuring full capacity is maintained during the update.</li></ul>" },
    { q: "Scenario: Your Elastic Beanstalk environment variables need to contain sensitive database passwords. How should you store them?", a: "<strong>Detailed Solution:</strong> Do not hardcode them in your configuration files.<br><ul><li><strong>Solution:</strong> Use AWS Systems Manager (SSM) Parameter Store or AWS Secrets Manager.</li><li><strong>Integration:</strong> Store the password securely in Secrets Manager. Modify your application code or environment configuration (.ebextensions) to retrieve the secret at runtime using the instance profile IAM role.</li></ul>" }
  ],
  "Advanced Scenario": [
    { q: "Scenario: You need to execute database migration scripts (e.g., schema updates) before deploying a new code version on Elastic Beanstalk. How?", a: "<strong>Detailed Solution:</strong> Use `.ebextensions` configuration files for pre-deployment commands.<br><ul><li><strong>Implementation:</strong> Create a `.ebextensions/db-migrate.config` file in your application bundle.</li><li><strong>Command:</strong> Use the <code>container_commands</code> block, which runs after the application and web server are set up, but before the application version is deployed to users. Use <code>leader_only: true</code> to ensure the migration only runs on one instance (to prevent race conditions in multi-instance environments).</li></ul>" }
  ]
};

