// AWS ▶ KMS
// ─────────────────────────────────────────────────────────────────────────────
window.interviewData["AWS ▶ KMS"] = {
  "Basic": [
    { q: "What is AWS KMS (Key Management Service)?", a: "<strong>Detailed Solution:</strong> KMS is a managed service that makes it easy for you to create and control the cryptographic keys used to protect your data.<br><ul><li><strong>Function:</strong> It uses Hardware Security Modules (HSMs) to protect and validate your AWS KMS keys.</li><li><strong>Integration:</strong> It is integrated with most other AWS services (EBS, S3, RDS, etc.) to encrypt data at rest.</li></ul>" },
    { q: "What is the difference between AWS Managed Keys and Customer Managed Keys (CMKs)?", a: "<strong>Detailed Solution:</strong> The level of control differs.<br><ul><li><strong>AWS Managed Keys:</strong> Created, managed, and used on your behalf by an AWS service (e.g., `aws/s3`). You cannot manage rotation or change key policies.</li><li><strong>Customer Managed Keys:</strong> Keys you create, manage, and control. You define the key policies, IAM policies, and rotation schedule.</li></ul>" }
  ],
  "Moderate Scenario": [
    { q: "Scenario: You need to share an encrypted EBS snapshot with another AWS account. How do you do this securely using KMS?", a: "<strong>Detailed Solution:</strong> Cross-account sharing requires a Customer Managed Key.<br><ul><li><strong>Requirement:</strong> You cannot share snapshots encrypted with an AWS Managed Key. You must use a Customer Managed Key (CMK).</li><li><strong>Key Policy:</strong> Update the KMS Key Policy of the CMK to grant `kms:Decrypt` and `kms:CreateGrant` permissions to the external account ID.</li><li><strong>Snapshot Policy:</strong> Modify the snapshot permissions to allow the external account to access it. The target account must then copy the snapshot and re-encrypt it with their own key.</li></ul>" },
    { q: "Scenario: A developer accidentally deleted a Customer Managed Key (CMK). What happens to the encrypted data?", a: "<strong>Detailed Solution:</strong> KMS has safeguards against immediate deletion.<br><ul><li><strong>Deletion State:</strong> KMS keys are never deleted immediately. When you schedule deletion, there is a mandatory waiting period (7 to 30 days). During this time, the key's state is 'Pending deletion' and it cannot be used for cryptographic operations.</li><li><strong>Recovery:</strong> You can cancel the deletion at any time during the waiting period. If the key is permanently deleted, all data encrypted by it becomes permanently unrecoverable.</li></ul>" }
  ],
  "Advanced Scenario": [
    { q: "Scenario: Your application needs to encrypt objects larger than 4KB using KMS before storing them in DynamoDB. How do you implement this?", a: "<strong>Detailed Solution:</strong> KMS has a strict 4KB limit for direct encryption. You must use Envelope Encryption.<br><ul><li><strong>Process:</strong> Your application calls the KMS `GenerateDataKey` API. KMS returns a plaintext data key and a ciphertext version of the data key (encrypted by the KMS Master Key).</li><li><strong>Encryption:</strong> Your application uses the plaintext data key to encrypt the large object locally.</li><li><strong>Storage:</strong> Discard the plaintext key from memory. Store the ciphertext data key alongside the encrypted object in DynamoDB.</li><li><strong>Decryption:</strong> Read the object, call KMS `Decrypt` on the ciphertext data key to get the plaintext key back, and then decrypt the object.</li></ul>" }
  ]
};

