window.interviewData["AWS ▶ CloudWatch"] = {
  "Basic": [
    { q: "What is Amazon CloudWatch?", a: "<strong>Detailed Solution:</strong> CloudWatch is a monitoring and observability service built for DevOps engineers, developers, and IT managers.<br><ul><li><strong>Metrics & Logs:</strong> It collects monitoring and operational data in the form of logs, metrics, and events.</li><li><strong>Alarms:</strong> You can set high-resolution alarms, visualize logs and metrics side by side, and take automated actions (like Auto Scaling or EC2 recovery) based on thresholds.</li></ul>" },
    { q: "What is the difference between standard and high-resolution custom metrics in CloudWatch?", a: "<strong>Detailed Solution:</strong> The difference is the granularity of data collection.<br><ul><li><strong>Standard Metrics:</strong> Have a 1-minute granularity (resolution). EC2 basic monitoring provides data every 5 minutes, while detailed monitoring provides data every 1 minute.</li><li><strong>High-Resolution Metrics:</strong> Custom metrics can be published with a resolution of 1 second. This allows for sub-minute alarming (e.g., a 10-second or 30-second alarm), which is critical for highly responsive auto-scaling workloads.</li></ul>" }
  ],
  "Moderate Scenario": [
    { q: "Scenario: You need to track application-level errors (e.g., 'NullPointerException') and trigger an alarm if there are more than 10 in 5 minutes. How?", a: "<strong>Detailed Solution:</strong> Use CloudWatch Logs Metric Filters.<br><ul><li><strong>Step 1:</strong> Stream your application logs to a CloudWatch Logs Log Group using the CloudWatch agent.</li><li><strong>Step 2:</strong> Create a Metric Filter on the Log Group that searches for the string `NullPointerException`. Set the metric value to `1` every time it's found.</li><li><strong>Step 3:</strong> Create a CloudWatch Alarm based on this custom metric, with a threshold of `>= 10` over a period of 5 minutes. Configure it to send an SNS notification to your team.</li></ul>" },
    { q: "Scenario: An EC2 instance occasionally becomes unresponsive due to underlying hardware failure. How can you automate recovery without manual intervention?", a: "<strong>Detailed Solution:</strong> Use CloudWatch EC2 Auto Recovery alarms.<br><ul><li><strong>Metric:</strong> Create a CloudWatch alarm for the `StatusCheckFailed_System` metric on the specific EC2 instance.</li><li><strong>Action:</strong> Set the alarm action to 'Recover this instance'.</li><li><strong>Behavior:</strong> If the underlying host fails, CloudWatch will automatically stop and restart the instance on healthy hardware in the same AZ, retaining its Instance ID, Private IP, Elastic IP, and EBS volume data.</li></ul>" }
  ],
  "Advanced Scenario": [
    { q: "Scenario: You want to execute a Lambda function precisely at 2:00 AM every Sunday to perform database cleanup. How do you orchestrate this natively in AWS?", a: "<strong>Detailed Solution:</strong> Use Amazon EventBridge (formerly CloudWatch Events).<br><ul><li><strong>Setup:</strong> Create an EventBridge Rule. Instead of an event pattern, choose 'Schedule'.</li><li><strong>Expression:</strong> Use a cron expression for 2:00 AM every Sunday (e.g., `cron(0 2 ? * SUN *)`).</li><li><strong>Target:</strong> Set the target of the rule to your specific AWS Lambda function. EventBridge will automatically trigger the Lambda on the defined schedule.</li></ul>" }
  ]
};

