// AWS ▶ SNS
// ─────────────────────────────────────────────────────────────────────────────
window.interviewData["AWS ▶ SNS"] = {
  "Basic": [
    { q: "What is Amazon SNS (Simple Notification Service)?", a: "<strong>Detailed Solution:</strong> SNS is a highly available, durable, secure, fully managed pub/sub messaging service.<br><ul><li><strong>Pub/Sub Model:</strong> Publishers send messages to 'Topics'. Subscribers receive the messages published to the topics they are subscribed to.</li><li><strong>Endpoints:</strong> SNS can fan out messages to a large number of subscriber endpoints, including SQS queues, AWS Lambda functions, HTTP/S webhooks, email, SMS, and mobile push notifications.</li></ul>" },
    { q: "What is the difference between SNS and SQS?", a: "<strong>Detailed Solution:</strong> SNS is pub/sub (push), while SQS is message queuing (pull).<br><ul><li><strong>SNS (Push):</strong> Messages are actively pushed to subscribers the moment they are published. If a subscriber is offline (e.g., a webhook is down), the message might be dropped after retries.</li><li><strong>SQS (Pull):</strong> Messages are stored in a queue until a consumer explicitly polls and pulls them. SQS guarantees delivery and retention (up to 14 days), enabling reliable, decoupled asynchronous processing.</li></ul>" }
  ],
  "Moderate Scenario": [
    { q: "Scenario: An application publishes order events to an SNS topic. You want to process 'premium' orders differently than 'standard' orders, using different Lambda functions, without processing standard orders in the premium Lambda.", a: "<strong>Detailed Solution:</strong> Use SNS Message Filtering.<br><ul><li><strong>Implementation:</strong> Apply a subscription filter policy to the premium Lambda's SNS subscription.</li><li><strong>Policy:</strong> Define the filter policy to only accept messages where the attribute `order_tier` is exactly `premium`.</li><li><strong>Result:</strong> When a message is published, SNS evaluates the message attributes against the filter policies. The premium Lambda will only be invoked for premium orders, saving compute costs and simplifying the Lambda logic.</li></ul>" },
    { q: "Scenario: An HTTPS webhook subscribed to an SNS topic is temporarily down for maintenance. How do you ensure messages are not permanently lost during this time?", a: "<strong>Detailed Solution:</strong> Attach a Dead-Letter Queue (DLQ) to the SNS subscription.<br><ul><li><strong>Mechanism:</strong> SNS has a built-in retry policy for HTTP endpoints. It will back off and retry delivery for a certain period.</li><li><strong>DLQ:</strong> If all delivery attempts fail, SNS can automatically move the undelivered message to an SQS queue designated as the DLQ for that subscription. Once the webhook is back online, you can inspect the DLQ and manually replay the messages.</li></ul>" }
  ],
  "Advanced Scenario": [
    { q: "Scenario: A globally distributed microservice architecture requires an SNS topic in us-east-1 to fan out messages to SQS queues located in eu-west-1, ap-southeast-2, and us-west-2 for localized processing. Is this possible, and how?", a: "<strong>Detailed Solution:</strong> Yes, SNS supports cross-region delivery to SQS queues.<br><ul><li><strong>Implementation:</strong> You can subscribe an SQS queue in any AWS region to an SNS topic in any other region.</li><li><strong>Permissions:</strong> The crucial step is the SQS Queue Policy. The SQS queue in eu-west-1 must have a resource-based policy that explicitly grants `sqs:SendMessage` permission to the SNS Topic ARN located in us-east-1. Without this cross-account/cross-region permission, SNS cannot deliver the message.</li></ul>" }
  ]
};

